begin;
    with j as (select * from jsonb_to_recordset($law7v007$[{"code_id":"GK_RF","article_number":"148","version_date":"1994-11-30","article_text":"1. Восстановление прав по утраченной ценной бумаге на предъявителя производится судом в порядке вызывного производства в соответствии с процессуальным законодательством по заявлению лица, утратившего ценную бумагу, о признании ее недействительной и восстановлении прав по ценной бумаге.\n\n2. Лицо, утратившее ордерную ценную бумагу, вправе заявить в письменной форме об этом всем обязанным по ней лицам с указанием причин утраты.\n\nОбязанное лицо, получившее заявление лица, утратившего ордерную ценную бумагу, в случае предъявления ее иным лицом должно приостановить исполнение предъявителю ценной бумаги и сообщить ему о притязаниях заявителя, а также сообщить заявителю о лице, предъявившем ценную бумагу. Если в течение трех месяцев со дня заявления лица об утрате ордерной ценной бумаги лицо, утратившее ценную бумагу, не обратилось в суд с соответствующим требованием к предъявителю ценной бумаги, обязанное лицо должно произвести исполнение предъявителю ценной бумаги. Если спор между лицом, утратившим ценную бумагу, и лицом, предъявившим ценную бумагу, разрешен судом, исполнение производится лицу, в пользу которого принято судебное решение.\n\nПри отсутствии спора о праве на ордерную ценную бумагу лицо, утратившее ее, вправе потребовать в судебном порядке исполнения от обязанного лица.\n\n3. Восстановление прав по утраченной именной документарной ценной бумаге производится судом в порядке особого производства по делам об установлении фактов, имеющих юридическое значение, в соответствии с процессуальным законодательством по заявлению лица, утратившего такую ценную бумагу, а в случаях, предусмотренных законом, также иных лиц.\n\n4. При утрате учетных записей о владельцах именных документарных ценных бумаг лицо, ведущее учет, обязано опубликовать незамедлительно информацию об этом в средствах массовой информации, в которых подлежат опубликованию сведения о банкротстве, и предложить лицам, которые были указаны в качестве правообладателей в учетных записях, представить именные ценные бумаги в срок, который указан при опубликовании информации и который не может быть менее трех месяцев с момента ее опубликования.\n\nУчетные записи о владельцах именных документарных ценных бумаг должны быть восстановлены лицом, ведущим такой учет, в течение месяца со дня окончания срока представления ценных бумаг их владельцами.\n\nПри уклонении лица, ведущего учет, от восстановления учетных записей они подлежат восстановлению судом по иску заинтересованного лица в порядке, установленном процессуальным законодательством.\n\n5. Лицо, обязанное по именной документарной ценной бумаге, и лицо, осуществляющее по его поручению учет прав на ценные бумаги, несут солидарную ответственность за убытки, причиненные владельцам таких ценных бумаг в результате утраты учетных записей или нарушения порядка и сроков восстановления таких записей, если не докажут, что утрата или нарушение имели место вследствие непреодолимой силы.","article_title":"Статья 148. Восстановление прав по документарной ценной бумаге","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"0fb6ee2348f57653404ec4b1af94419c4ff77887385da623871446a12618ac5f"},{"code_id":"GK_RF","article_number":"148.1","version_date":"1994-11-30","article_text":"В соответствии с законом или в установленном им порядке документарные ценные бумаги могут быть обездвижены, то есть переданы на хранение лицу, которое в соответствии с законом вправе осуществлять хранение документарных ценных бумаг и (или) учет прав на ценные бумаги. Переход прав на обездвиженные ценные бумаги и осуществление прав, удостоверенных такими ценными бумагами, регулируются статьями 149 - 1495 настоящего Кодекса, если иное не предусмотрено законом.","article_title":"Статья 148.1. Обездвижение документарных ценных бумаг","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"43484011cc978591eb0bcdaaab4e956c75c25771a69310bcf00bd135f51a4a29"},{"code_id":"GK_RF","article_number":"149","version_date":"1994-11-30","article_text":"1. Лицами, ответственными за исполнение по бездокументарной ценной бумаге, являются лицо, которое выпустило ценную бумагу, а также лица, которые предоставили обеспечение исполнения соответствующего обязательства. Лица, ответственные за исполнение по бездокументарной ценной бумаге, должны быть указаны в решении о ее выпуске или в ином предусмотренном законом акте лица, выпустившего ценную бумагу.\n\nПраво требовать от обязанного лица исполнения по бездокументарной ценной бумаге признается за лицом, указанным в учетных записях в качестве правообладателя, или за иным лицом, которое в соответствии с законом осуществляет права по ценной бумаге.\n\n2. Учет прав на бездокументарные ценные бумаги осуществляется путем внесения записей по счетам лицом, действующим по поручению лица, обязанного по ценной бумаге, либо лицом, действующим на основании договора с правообладателем или с иным лицом, которое в соответствии с законом осуществляет права по ценной бумаге. Ведение записей по учету таких прав осуществляется лицом, имеющим предусмотренную законом лицензию.\n\n3. Распоряжение, в том числе передача, залог, обременение другими способами бездокументарных ценных бумаг, а также ограничения распоряжения ими могут осуществляться только посредством обращения к лицу, осуществляющему учет прав на бездокументарные ценные бумаги, для внесения соответствующих записей.\n\n4. Лицо, выпустившее бездокументарную ценную бумагу, и лицо, осуществляющее по его поручению учет прав на такие ценные бумаги, несут солидарную ответственность за убытки, причиненные в результате нарушения порядка учета прав, порядка совершения операций по счетам, утраты учетных данных, предоставления недостоверной информации об учетных данных, если не докажут, что нарушение имело место вследствие непреодолимой силы.\n\nЛицо, ответственное за исполнение по бездокументарной ценной бумаге, не несет ответственность за убытки, причиненные в результате нарушения порядка учета прав лицами, действующими на основании договора с правообладателем или с иным лицом, которое в соответствии с законом осуществляет права по ценной бумаге.","article_title":"Статья 149. Общие положения о бездокументарных ценных бумагах","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"ec2b74930e2c886d032ca3ac08716d8599885a8d7d306ceb84850943b26800ae"},{"code_id":"GK_RF","article_number":"149.1","version_date":"1994-11-30","article_text":"1. Надлежащим исполнением по бездокументарной ценной бумаге признается исполнение, произведенное обязанным лицом лицам, указанным в абзаце втором пункта 1 статьи 149 настоящего Кодекса.\n\nЗаконом могут быть установлены случаи, когда на определенную дату фиксируется перечень лиц, имеющих право требовать исполнения по бездокументарным ценным бумагам. Надлежащим признается исполнение, произведенное таким лицам.\n\n2. В случаях, предусмотренных законом, надлежащим признается исполнение лицам иным, чем те, которые указаны в пункте 1 настоящей статьи.\n\n3. Правила, предусмотренные пунктом 2 статьи 144 и статьей 145 настоящего Кодекса, применяются к отношениям, связанным с исполнением по бездокументарным ценным бумагам, если это не противоречит существу таких ценных бумаг.","article_title":"Статья 149.1. Исполнение по бездокументарной ценной бумаге","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"f899df6911da457ab6dbcee96d134c0089a3d6e350e79a8d01e4e8b1aa3e50a4"},{"code_id":"GK_RF","article_number":"149.2","version_date":"1994-11-30","article_text":"1. Передача прав на бездокументарные ценные бумаги приобретателю осуществляется посредством списания бездокументарных ценных бумаг со счета лица, совершившего их отчуждение, и зачисления их на счет приобретателя на основании распоряжения лица, совершившего отчуждение. Законом или договором правообладателя с лицом, осуществляющим учет прав на бездокументарные ценные бумаги, могут быть предусмотрены иные основания и условия списания ценных бумаг и их зачисления, в том числе возможность списания ценных бумаг со счета лица, совершившего отчуждение, без представления его распоряжения.\n\n2. Права по бездокументарной ценной бумаге переходят к приобретателю с момента внесения лицом, осуществляющим учет прав на бездокументарные ценные бумаги, соответствующей записи по счету приобретателя.\n\n3. Залог, обременение другими способами бездокументарных ценных бумаг, а также ограничения распоряжения ими возникают после внесения лицом, осуществляющим учет прав, соответствующей записи о залоге, обременении или ограничении по счету правообладателя либо в установленных законом случаях по счету иного лица.\n\nОбременение бездокументарных ценных бумаг может также возникать с момента их зачисления на счет, на котором в соответствии с законом учитываются права на обремененные бездокументарные ценные бумаги.\n\nВнесение записей о залоге или об ином обременении бездокументарных ценных бумаг производится на основании распоряжения правообладателя (залоговое распоряжение и т.п.), если иное не предусмотрено законом. Записи об изменении условий обременения и о его прекращении вносятся на основании распоряжения правообладателя при наличии согласия в письменной форме лица, в пользу которого установлено обременение, либо без такого распоряжения в случаях, предусмотренных законом или соглашением правообладателя с лицом, осуществляющим учет прав на бездокументарные ценные бумаги, и лицом, в пользу которого установлено обременение.\n\n4. При уклонении лица, совершившего отчуждение, либо лица, предоставляющего ценные бумаги в обеспечение исполнения обязательства, от представления лицу, осуществляющему учет прав на бездокументарные ценные бумаги, распоряжения о проведении операции по счету приобретатель или лицо, в пользу которого устанавливается обременение бездокументарных ценных бумаг, вправе требовать в судебном порядке внесения записей о переходе прав на ценные бумаги или об их обременении на условиях, предусмотренных договором с лицом, совершающим отчуждение, или с лицом, предоставляющим ценные бумаги в обеспечение исполнения обязательства.\n\nПри наличии нескольких лиц, в пользу которых установлено обязательство по передаче либо обременению прав на одни и те же бездокументарные ценные бумаги, в случае, если операция по их передаче или по обременению еще не осуществлена, преимущество имеет лицо, в пользу которого обязательство возникло ранее, а если это невозможно установить - лицо, первым предъявившее иск.\n\n5. Оформление перехода прав на бездокументарные ценные бумаги в порядке наследования производится на основании представленного наследником свидетельства о праве на наследство (статья 1162).\n\nПереход прав на бездокументарные ценные бумаги при реализации таких ценных бумаг в случае обращения на них взыскания оформляется на основании распоряжения лица, уполномоченного на реализацию имущества правообладателя.\n\nОформление передачи прав на бездокументарные ценные бумаги в соответствии с судебным решением производится лицом, осуществляющим учет прав, на основании решения суда или на основании акта лица, осуществляющего исполнение судебного решения.\n\n6. Уклонение или отказ лица, осуществляющего учет прав на бездокументарные ценные бумаги, от проведения операции по счету могут быть оспорены в суде.","article_title":"Статья 149.2. Переход прав по бездокументарной ценной бумаге и возникновение обременения бездокументарной ценной бумаги","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"8f1e90b42f1e3d55e5de7ab9ec532675d8bce3fa50c78b6643c3d45ddeac149f"},{"code_id":"GK_RF","article_number":"149.3","version_date":"1994-11-30","article_text":"1. Правообладатель, со счета которого были неправомерно списаны бездокументарные ценные бумаги, вправе требовать от лица, на счет которого ценные бумаги были зачислены, возврата такого же количества соответствующих ценных бумаг.\n\nБездокументарные ценные бумаги, удостоверяющие только денежное право требования, а также бездокументарные ценные бумаги, приобретенные на организованных торгах, независимо от вида удостоверяемого права не могут быть истребованы от добросовестного приобретателя.\n\nЕсли бездокументарные ценные бумаги были безвозмездно приобретены у лица, которое не имело права их отчуждать, правообладатель вправе истребовать такие ценные бумаги во всех случаях.\n\n2. Если бездокументарные ценные бумаги, которые правообладатель вправе истребовать, были конвертированы в другие ценные бумаги, правообладатель вправе истребовать те ценные бумаги, в которые были конвертированы ценные бумаги, списанные с его счета.\n\n3. Правообладатель, со счета которого бездокументарные ценные бумаги были неправомерно списаны, при наличии возможности приобретения таких же ценных бумаг на организованных торгах по своему выбору вправе потребовать от лиц, несущих перед ним ответственность за причиненные этим убытки, приобретения таких же ценных бумаг за их счет либо возмещения всех необходимых для их приобретения расходов.","article_title":"Статья 149.3. Защита нарушенных прав правообладателей","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"e20387b22f463460919a462611e4416d8b8fa99318ecd73094bc3caa09f48f4f"},{"code_id":"GK_RF","article_number":"149.4","version_date":"1994-11-30","article_text":"1. В случае удовлетворения требования правообладателя о возврате бездокументарных ценных бумаг в соответствии с пунктом 1 или пунктом 2 статьи 1493 настоящего Кодекса правообладатель пользуется в отношении лица, со счета которого ценные бумаги были ему возвращены, правами, указанными в пункте 5 статьи 1471 настоящего Кодекса.\n\n2. В случае реализации неуправомоченными лицами удостоверенных бездокументарными ценными бумагами права на участие в управлении акционерным обществом или иного права на участие в принятии решения собрания правообладатель может оспорить соответствующее решение собрания, нарушающее его права и охраняемые законом интересы, если акционерное общество или лица, волеизъявление которых имело значение при принятии решения собрания, знали или должны были знать о наличии спора о правах на бездокументарные ценные бумаги и голосование правообладателя могло повлиять на принятие решения.\n\nИск об оспаривании решения собрания может быть предъявлен в течение трех месяцев со дня, когда лицо, имеющее право на ценную бумагу, узнало или должно было узнать о неправомерном списании ценных бумаг с его счета, но не позднее одного года со дня принятия соответствующего решения.\n\nСуд может оставить решение собрания в силе, если признание решения недействительным повлечет причинение несоразмерного ущерба кредиторам акционерного общества или иным третьим лицам.","article_title":"Статья 149.4. Последствия истребования бездокументарных ценных бумаг","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"c17d30276919b4756f43e2693bd72bf07a92de020956d9d0c136194c9a03f352"},{"code_id":"GK_RF","article_number":"149.5","version_date":"1994-11-30","article_text":"1. При утрате учетных записей, удостоверяющих права на бездокументарные ценные бумаги, лицо, осуществляющее учет прав, обязано незамедлительно опубликовать информацию об этом в средствах массовой информации, в которых подлежат опубликованию сведения о банкротстве, и обратиться в суд с заявлением о восстановлении данных учета прав в порядке, установленном процессуальным законодательством.\n\nТребование о восстановлении данных учета прав на бездокументарные ценные бумаги может быть заявлено любым заинтересованным лицом. Восстановление данных учета прав осуществляется в порядке, установленном процессуальным законодательством. При восстановлении данных учета прав на бездокументарные ценные бумаги записи о правообладателях вносятся на основании решения суда.\n\nИнформация о восстановлении данных учета прав на бездокументарные ценные бумаги опубликовывается для всеобщего сведения в средствах массовой информации, в которых подлежат опубликованию сведения о банкротстве, на основании решения суда за счет лица, осуществлявшего этот учет на момент утраты учетных записей, удостоверявших права на бездокументарные ценные бумаги.\n\n2. Записи об учете прав на бездокументарные ценные бумаги не имеют силы с момента, когда лицо, осуществляющее учет прав, утратило учетные записи, и до дня вступления в законную силу решения суда о восстановлении данных учета прав.","article_title":"Статья 149.5. Последствия утраты учетных записей, удостоверяющих права на бездокументарные ценные бумаги","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"b6f7be78a10b70bfa9d2d7c9f94a676a8ab48ad60abc4f30636c6b4068ec7bf6"},{"code_id":"GK_RF","article_number":"15","version_date":"1994-11-30","article_text":"1. Лицо, право которого нарушено, может требовать полного возмещения причиненных ему убытков, если законом или договором не предусмотрено возмещение убытков в меньшем размере.\n\n2. Под убытками понимаются расходы, которые лицо, чье право нарушено, произвело или должно будет произвести для восстановления нарушенного права, утрата или повреждение его имущества (реальный ущерб), а также неполученные доходы, которые это лицо получило бы при обычных условиях гражданского оборота, если бы его право не было нарушено (упущенная выгода).\n\nЕсли лицо, нарушившее право, получило вследствие этого доходы, лицо, право которого нарушено, вправе требовать возмещения наряду с другими убытками упущенной выгоды в размере не меньшем, чем такие доходы.","article_title":"Статья 15. Возмещение убытков","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"fa0ed33016de2dca4ef3b2ebc462e99e9c1377fdfc9f10c3296bdf565989edd2"},{"code_id":"GK_RF","article_number":"150","version_date":"1994-11-30","article_text":"1. Жизнь и здоровье, достоинство личности, личная неприкосновенность, честь и доброе имя, деловая репутация, неприкосновенность частной жизни, неприкосновенность жилища, личная и семейная тайна, свобода передвижения, свобода выбора места пребывания и жительства, имя гражданина, авторство, иные нематериальные блага, принадлежащие гражданину от рождения или в силу закона, неотчуждаемы и непередаваемы иным способом.\n\n2. Нематериальные блага защищаются в соответствии с настоящим Кодек\n\nсом и другими законами в случаях и в порядке, ими предусмотренных, а также в тех случаях и пределах, в каких использование способов защиты гражданских прав (статья 12) вытекает из существа нарушенного нематериального блага или личного неимущественного права и характера последствий этого нарушения.\n\nВ случаях, если того требуют интересы гражданина, принадлежащие ему нематериальные блага могут быть защищены, в частности, путем признания судом факта нарушения его личного неимущественного права, опубликования решения суда о допущенном нарушении, а также путем пресечения или запрещения действий, нарушающих или создающих угрозу нарушения личного неимущественного права либо посягающих или создающих угрозу посягательства на нематериальное благо.\n\nВ случаях и в порядке, которые предусмотрены законом, нематериальные блага, принадлежавшие умершему, могут защищаться другими лицами.\n\n(Статья в редакции Федерального закона от 02.07.2013 № 142-ФЗ)","article_title":"Статья 150. Нематериальные блага","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"e6f0de3b5a028c408a76436211a03babf585e114b7eea107de3445203d258bd4"},{"code_id":"GK_RF","article_number":"151","version_date":"1994-11-30","article_text":"Если гражданину причинен моральный вред (физические или нравственные страдания) действиями, нарушающими его личные неимущественные права либо посягающими на принадлежащие гражданину нематериальные блага, а также в других случаях, предусмотренных законом, суд может возложить на нарушителя обязанность денежной компенсации указанного вреда. (В редакции Федерального закона от 02.07.2013 № 142-ФЗ)\n\nПри определении размеров компенсации морального вреда суд принимает во внимание степень вины нарушителя и иные заслуживающие внимания обстоятельства. Суд должен также учитывать степень физических и нравственных страданий, связанных с индивидуальными особенностями гражданина, которому причинен вред. (В редакции Федерального закона от 02.07.2013 № 142-ФЗ)","article_title":"Статья 151. Компенсация морального вреда","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"daccc1852096e061043ac5adb42e3e02cfa24d42510ed673f3fcd2134d5ded0b"},{"code_id":"GK_RF","article_number":"152","version_date":"1994-11-30","article_text":"1. Гражданин вправе требовать по суду опровержения порочащих его честь, достоинство или деловую репутацию сведений, если распространивший такие сведения не докажет, что они соответствуют действительности. Опровержение должно быть сделано тем же способом, которым были распространены сведения о гражданине, или другим аналогичным способом.\n\nПо требованию заинтересованных лиц допускается защита чести, достоинства и деловой репутации гражданина и после его смерти.\n\n2. Сведения, порочащие честь, достоинство или деловую репутацию гражданина и распространенные в средствах массовой информации, должны быть опровергнуты в тех же средствах массовой информации. Гражданин, в отношении которого в средствах массовой информации распространены указанные сведения, имеет право потребовать наряду с опровержением также опубликования своего ответа в тех же средствах массовой информации.\n\n3. Если сведения, порочащие честь, достоинство или деловую репутацию гражданина, содержатся в документе, исходящем от организации, такой документ подлежит замене или отзыву.\n\n4. В случаях, когда сведения, порочащие честь, достоинство или деловую репутацию гражданина, стали широко известны и в связи с этим опровержение невозможно довести до всеобщего сведения, гражданин вправе требовать удаления соответствующей информации, а также пресечения или запрещения дальнейшего распространения указанных сведений путем изъятия и уничтожения без какой бы то ни было компенсации изготовленных в целях введения в гражданский оборот экземпляров материальных носителей, содержащих указанные сведения, если без уничтожения таких экземпляров материальных носителей удаление соответствующей информации невозможно.\n\n5. Если сведения, порочащие честь, достоинство или деловую репутацию гражданина, оказались после их распространения доступными в сети \"Интернет\", гражданин вправе требовать удаления соответствующей информации, а также опровержения указанных сведений способом, обеспечивающим доведение опровержения до пользователей сети \"Интернет\".\n\n6. Порядок опровержения сведений, порочащих честь, достоинство или деловую репутацию гражданина, в иных случаях, кроме указанных в пунктах 2 - 5 настоящей статьи, устанавливается судом.\n\n7. Применение к нарушителю мер ответственности за неисполнение судебного решения не освобождает его от обязанности совершить предусмотренное решением суда действие.\n\n8. Если установить лицо, распространившее сведения, порочащие честь, достоинство или деловую репутацию гражданина, невозможно, гражданин, в отношении которого такие сведения распространены, вправе обратиться в суд с заявлением о признании распространенных сведений не соответствующими действительности.\n\n9. Гражданин, в отношении которого распространены сведения, порочащие его честь, достоинство или деловую репутацию, наряду с опровержением таких сведений или опубликованием своего ответа вправе требовать возмещения убытков и компенсации морального вреда, причиненных распространением таких сведений.\n\n10. Правила пунктов 1 - 9 настоящей статьи, за исключением положений о компенсации морального вреда, могут быть применены судом также к случаям распространения любых не соответствующих действительности сведений о гражданине, если такой гражданин докажет несоответствие указанных сведений действительности. Срок исковой давности по требованиям, предъявляемым в связи с распространением указанных сведений в средствах массовой информации, составляет один год со дня опубликования таких сведений в соответствующих средствах массовой информации.\n\n11. Правила настоящей статьи о защите деловой репутации гражданина, за исключением положений о компенсации морального вреда, соответственно применяются к защите деловой репутации юридического лица.\n\n(Статья в редакции Федерального закона от 02.07.2013 № 142-ФЗ)","article_title":"Статья 152. Защита чести, достоинства и деловой репутации","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"95dd86cdf58fb186ef09e9d2dd5dbaad1c7ea09eb704036178a66beeab69cff8"},{"code_id":"GK_RF","article_number":"152.1","version_date":"1994-11-30","article_text":"1) использование изображения осуществляется в государственных, общественных или иных публичных интересах;\n\n2) изображение гражданина получено при съемке, которая проводится в местах, открытых для свободного посещения, или на публичных мероприятиях (собраниях, съездах, конференциях, концертах, представлениях, спортивных соревнованиях и подобных мероприятиях), за исключением случаев, когда такое изображение является основным объектом использования;\n\n3) гражданин позировал за плату.\n\n(Дополнение статьей - Федеральный закон от 18.12.2006 № 231-ФЗ)","article_title":"Статья 152.1. Охрана изображения гражданина","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"789d31efeafd7ed1927c17968d6e809e5c944232535b3e9f47ff916d4ecfde3c"},{"code_id":"GK_RF","article_number":"152.2","version_date":"1994-11-30","article_text":"1. Если иное прямо не предусмотрено законом, не допускаются без согласия гражданина сбор, хранение, распространение и использование любой информации о его частной жизни, в частности сведений о его происхождении, о месте его пребывания или жительства, о личной и семейной жизни.\n\nНе являются нарушением правил, установленных абзацем первым настоящего пункта, сбор, хранение, распространение и использование информации о частной жизни гражданина в государственных, общественных или иных публичных интересах, а также в случаях, если информация о частной жизни гражданина ранее стала общедоступной либо была раскрыта самим гражданином или по его воле.\n\n2. Стороны обязательства не вправе разглашать ставшую известной им при возникновении и (или) исполнении обязательства информацию о частной жизни гражданина, являющегося стороной или третьим лицом в данном обязательстве, если соглашением не предусмотрена возможность такого разглашения информации о сторонах.\n\n3. Неправомерным распространением полученной с нарушением закона информации о частной жизни гражданина считается, в частности, ее использование при создании произведений науки, литературы и искусства, если такое использование нарушает интересы гражданина.\n\n4. В случаях, когда информация о частной жизни гражданина, полученная с нарушением закона, содержится в документах, видеозаписях или на иных материальных носителях, гражданин вправе обратиться в суд с требованием об удалении соответствующей информации, а также о пресечении или запрещении дальнейшего ее распространения путем изъятия и уничтожения без какой бы то ни было компенсации изготовленных в целях введения в гражданский оборот экземпляров материальных носителей, содержащих соответствующую информацию, если без уничтожения таких экземпляров материальных носителей удаление соответствующей информации невозможно.\n\n5. Право требовать защиты частной жизни гражданина способами, предусмотренными пунктом 2 статьи 150 настоящего Кодекса и настоящей статьей, в случае его смерти имеют дети, родители и переживший супруг такого гражданина.\n\n(Дополнение статьей - Федеральный закон от 02.07.2013 № 142-ФЗ)\n\n(Наименование в редакции Федерального закона от 07.05.2013 № 100-ФЗ)","article_title":"Статья 152.2. Охрана частной жизни гражданина","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"8d897b28c78a48a6caf5e960a1b59509c47e88668ce4bb5a820f79f2ca227b9d"},{"code_id":"GK_RF","article_number":"153","version_date":"1994-11-30","article_text":"Сделками признаются действия граждан и юридических лиц, направленные на установление, изменение или прекращение гражданских прав и обязанностей.","article_title":"Статья 153. Понятие сделки","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"121d8cc077d974019bab6bd7099539c81daa39651070d0247ab623b9350e978a"},{"code_id":"GK_RF","article_number":"154","version_date":"1994-11-30","article_text":"1. Сделки могут быть двух- или многосторонними (договоры) и односторонними.\n\n2. Односторонней считается сделка, для совершения которой в соответствии с законом, иными правовыми актами или соглашением сторон необходимо и достаточно выражения воли одной стороны.\n\n3. Для заключения договора необходимо выражение согласованной воли двух сторон (двусторонняя сделка) либо трех или более сторон (многосторонняя сделка).","article_title":"Статья 154. Договоры и односторонние сделки","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"44fed5f1381b7975dd9f59955e45bf7e4a0855fbd170c404f866a8edb7dd4110"},{"code_id":"GK_RF","article_number":"155","version_date":"1994-11-30","article_text":"Односторонняя сделка создает обязанности для лица, совершившего сделку. Она может создавать обязанности для других лиц лишь в случаях, установленных законом либо соглашением с этими лицами.","article_title":"Статья 155. Обязанности по односторонней сделке","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"1e7b5d73e81b9088fe7b3fc69cd2db71f6fcf5cd29b92b1da31a44405b26c3a9"},{"code_id":"GK_RF","article_number":"156","version_date":"1994-11-30","article_text":"К односторонним сделкам соответственно применяются общие положения об обязательствах и о договорах, поскольку это не противоречит закону, одностороннему характеру и существу сделки. (В редакции Федерального закона от 07.05.2013 № 100-ФЗ)","article_title":"Статья 156. Правовое регулирование односторонних сделок","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"76eb3f3abcb69b1f71bb596d148f970159dab69589e604f9c0117af640ad49d3"},{"code_id":"GK_RF","article_number":"157","version_date":"1994-11-30","article_text":"1. Сделка считается совершенной под отлагательным условием, если стороны поставили возникновение прав и обязанностей в зависимость от обстоятельства, относительно которого неизвестно, наступит оно или не наступит.\n\n2. Сделка считается совершенной под отменительным условием, если стороны поставили прекращение прав и обязанностей в зависимость от обстоятельства, относительно которого неизвестно, наступит оно или не наступит.\n\n3. Если наступлению условия недобросовестно воспрепятствовала сторона, которой наступление условия невыгодно, то условие признается наступившим.\n\nЕсли наступлению условия недобросовестно содействовала сторона, которой наступление условия выгодно, то условие признается ненаступившим.","article_title":"Статья 157. Сделки, совершенные под условием","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"f5ae78b1a46a62ea9c929f14707d2b7bff3bac352b058c721dbe1900d4829bdc"},{"code_id":"GK_RF","article_number":"157.1","version_date":"1994-11-30","article_text":"1. Правила настоящей статьи применяются, если другое не предусмотрено законом или иным правовым актом.\n\n2. Если на совершение сделки в силу закона требуется согласие третьего лица, органа юридического лица или государственного органа либо органа местного самоуправления, о своем согласии или об отказе в нем третье лицо или соответствующий орган сообщает лицу, запросившему согласие, либо иному заинтересованному лицу в разумный срок после получения обращения лица, запросившего согласие.\n\n3. В предварительном согласии на совершение сделки должен быть определен предмет сделки, на совершение которой дается согласие.\n\nПри последующем согласии (одобрении) должна быть указана сделка, на совершение которой дано согласие.\n\n4. Молчание не считается согласием на совершение сделки, за исключением случаев, установленных законом.\n\n(Дополнение статьей - Федеральный закон от 07.05.2013 № 100-ФЗ)","article_title":"Статья 157.1. Согласие на совершение сделки","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"06f6d61d5cf8ac9294775fee86114918b3b602abcbdbc7f07d3b0ac2bf0928af"},{"code_id":"GK_RF","article_number":"158","version_date":"1994-11-30","article_text":"1. Сделки совершаются устно или в письменной форме (простой или нотариальной).\n\n2. Сделка, которая может быть совершена устно, считается совершенной и в том случае, когда из поведения лица явствует его воля совершить сделку.\n\n3. Молчание признается выражением воли совершить сделку в случаях, предусмотренных законом или соглашением сторон.","article_title":"Статья 158. Форма сделок","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"cf06c2691b4981b954d98ffe1c8673a80b04fb1a1bd6f2c66a50e520f02c6895"},{"code_id":"GK_RF","article_number":"159","version_date":"1994-11-30","article_text":"1. Сделка, для которой законом или соглашением сторон не установлена письменная (простая или нотариальная) форма, может быть совершена устно.\n\n2. Если иное не установлено соглашением сторон, могут совершаться устно все сделки, исполняемые при самом их совершении, за исключением сделок, для которых установлена нотариальная форма, и сделок, несоблюдение простой письменной формы которых влечет их недействительность.\n\n3. Сделки во исполнение договора, заключенного в письменной форме, могут по соглашению сторон совершаться устно, если это не противоречит закону, иным правовым актам и договору.","article_title":"Статья 159. Устные сделки","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"1ed85b518e6eb10fbc608642e06d83e68e62690b3c0851daf62927ddc5a138fe"},{"code_id":"GK_RF","article_number":"16","version_date":"1994-11-30","article_text":"Убытки, причиненные гражданину или юридическому лицу в результате незаконных действий (бездействия) государственных органов, органов местного самоуправления или должностных лиц этих органов, в том числе издания не соответствующего закону или иному правовому акту акта государственного органа или органа местного самоуправления, подлежат возмещению Российской Федерацией, соответствующим субъектом Российской Федерации или муниципальным образованием.","article_title":"Статья 16. Возмещение убытков, причиненных государственными органами и органами местного самоуправления","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"90af24f3037b60c591e83e568771fa17dae72d41fe809f3844a9cc103d94ebd4"},{"code_id":"GK_RF","article_number":"160","version_date":"1994-11-30","article_text":"1. Сделка в письменной форме должна быть совершена путем составления документа, выражающего ее содержание и подписанного лицом или лицами, совершающими сделку, либо должным образом уполномоченными ими лицами.\n\nПисьменная форма сделки считается соблюденной также в случае совершения лицом сделки с помощью электронных либо иных технических средств, позволяющих воспроизвести на материальном носителе в неизменном виде содержание сделки, при этом требование о наличии подписи считается выполненным, если использован любой способ, позволяющий достоверно определить лицо, выразившее волю. Законом, иными правовыми актами и соглашением сторон может быть предусмотрен специальный способ достоверного определения лица, выразившего волю.\n\nДвусторонние (многосторонние) сделки могут совершаться способами, установленными пунктами 2 и 3 статьи 434 настоящего Кодекса.\n\nЗаконом, иными правовыми актами и соглашением сторон могут устанавливаться дополнительные требования, которым должна соответствовать форма сделки (совершение на бланке определенной формы, скрепление печатью и тому подобное), и предусматриваться последствия несоблюдения этих требований. Если такие последствия не предусмотрены, применяются последствия несоблюдения простой письменной формы сделки (пункт 1 статьи 162).\n\n(Пункт в редакции Федерального закона от 18.03.2019 № 34-ФЗ)\n\nПри совершении доверенностей, указанных в пункте 3 статьи 1851 настоящего Кодекса, подпись того, кто подписывает доверенность, может быть удостоверена также организацией, где работает гражданин, который не может собственноручно подписаться, или администрацией медицинской организации, в которой он находится на излечении в стационарных условиях. (В редакции Федерального закона от 23.05.2018 № 116-ФЗ)","article_title":"Статья 160. Письменная форма сделки","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"21b23a23768e8d9da9a72050c6b0b56cf6983fca6bf210dd72c4e0de319c9804"},{"code_id":"GK_RF","article_number":"16.1","version_date":"1994-11-30","article_text":"В случаях и в порядке, которые предусмотрены законом, ущерб, причиненный личности или имуществу гражданина либо имуществу юридического лица правомерными действиями государственных органов, органов местного самоуправления или должностных лиц этих органов, а также иных лиц, которым государством делегированы властные полномочия, подлежит компенсации.\n\n(Дополнение статьей - Федеральный закон от 30.12.2012 № 302-ФЗ)","article_title":"Статья 16.1. Компенсация ущерба, причиненного правомерными действиями государственных органов и органов местного самоуправления","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"1e7f2400db9b8540711000f34f74963166747a116996afdf7c9d3c00b4a9ac3c"},{"code_id":"GK_RF","article_number":"161","version_date":"1994-11-30","article_text":"1. Должны совершаться в простой письменной форме, за исключением сделок, требующих нотариального удостоверения:\n\n1) сделки юридических лиц между собой и с гражданами;\n\n2) сделки граждан между собой на сумму, превышающую десять тысяч рублей, а в случаях, предусмотренных законом, - независимо от суммы сделки. (В редакции Федерального закона от 07.05.2013 № 100-ФЗ)\n\n2. Соблюдение простой письменной формы не требуется для сделок, которые в соответствии со статьей 159 настоящего Кодекса могут быть совершены устно.","article_title":"Статья 161. Сделки, совершаемые в простой письменной форме","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"4abf3e178d4ceff8d26c43c62a29ad46791bf76efcce1ac7820df23a6cc68483"},{"code_id":"GK_RF","article_number":"162","version_date":"1994-11-30","article_text":"1. Несоблюдение простой письменной формы сделки лишает стороны права в случае спора ссылаться в подтверждение сделки и ее условий на свидетельские показания, но не лишает их права приводить письменные и другие доказательства.\n\n2. В случаях, прямо указанных в законе или в соглашении сторон, несоблюдение простой письменной формы сделки влечет ее недействительность.","article_title":"Статья 162. Последствия несоблюдения простой письменной формы сделки","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"3abcc9cef755906473b1a03184e7b2e6b0e80a2bb95ee4cb97706f70395c1ba7"},{"code_id":"GK_RF","article_number":"163","version_date":"1994-11-30","article_text":"(Наименование в редакции Федерального закона от 07.05.2013 № 100-ФЗ)\n\n1) в случаях, указанных в законе;\n\n2) в случаях, предусмотренных соглашением сторон, хотя бы по закону для сделок данного вида эта форма не требовалась.","article_title":"Статья 163. Нотариальное удостоверение сделки","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"20903d2d9df10ac81338f8458c9751d3806cf14fbe866e88b491c36f03f8f195"},{"code_id":"GK_RF","article_number":"164","version_date":"1994-11-30","article_text":"1. В случаях, если законом предусмотрена государственная регистрация сделок, правовые последствия сделки наступают после ее регистрации.\n\n2. Сделка, предусматривающая изменение условий зарегистрированной сделки, подлежит государственной регистрации.\n\n(Статья в редакции Федерального закона от 07.05.2013 № 100-ФЗ)","article_title":"Статья 164. Государственная регистрация сделок","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"2a2d97512a1dee7bd0b87a775c6aa821645fea349d0d708dd0c7289d2516ac47"},{"code_id":"GK_RF","article_number":"165","version_date":"1994-11-30","article_text":"1. Если одна из сторон полностью или частично исполнила сделку, требующую нотариального удостоверения, а другая сторона уклоняется от такого удостоверения сделки, суд по требованию исполнившей сделку стороны вправе признать сделку действительной. В этом случае последующее нотариальное удостоверение сделки не требуется.\n\n2. Если сделка, требующая государственной регистрации, совершена в надлежащей форме, но одна из сторон уклоняется от ее регистрации, суд по требованию другой стороны вправе вынести решение о регистрации сделки. В этом случае сд\n\nелка регистрируется в соответствии с решением суда.\n\n3. В случаях, предусмотренных пунктами 1 и 2 настоящей статьи, сторона, необоснованно уклоняющаяся от нотариального удостоверения или государственной регистрации сделки, должна возместить другой стороне убытки, вызванные задержкой в совершении или регистрации сделки.\n\n4. Срок исковой давности по требованиям, указанным в настоящей статье, составляет один год.\n\n(Статья в редакции Федерального закона от 07.05.2013 № 100-ФЗ)","article_title":"Статья 165. Последствия уклонения от нотариального удостоверения или государственной регистрации сделки","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"3f5f38a6754b97d178469fb9d9fd08eb6b7eec6c6eb750303d5f440aab462194"},{"code_id":"GK_RF","article_number":"165.1","version_date":"1994-11-30","article_text":"1. Заявления, уведомления, извещения, требования или иные юридически значимые сообщения, с которыми закон или сделка связывает гражданско-правовые последствия для другого лица, влекут для этого лица такие последствия с момента доставки соответствующего сообщения ему или его представителю.\n\nСообщение считается доставленным и в тех случаях, если оно поступило лицу, которому оно направлено (адресату), но по обстоятельствам, зависящим от него, не было ему вручено или адресат не ознакомился с ним.\n\n2. Правила пункта 1 настоящей статьи применяются, если иное не предусмотрено законом или условиями сделки либо не следует из обычая или из практики, установившейся во взаимоотношениях сторон.\n\n(Дополнение статьей - Федеральный закон от 07.05.2013 № 100-ФЗ)","article_title":"Статья 165.1. Юридически значимые сообщения","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"b17098bff5b090a50b34e1779004bf13c5c3cfd5443bc75a6e0de04994ea973b"},{"code_id":"GK_RF","article_number":"166","version_date":"1994-11-30","article_text":"1. Сделка недействительна по основаниям, установленным законом, в силу признания ее таковой судом (оспоримая сделка) либо независимо от такого признания (ничтожная сделка).\n\n2. Требование о признании оспоримой сделки недействительной может быть предъявлено стороной сделки или иным лицом, указанным в законе.\n\nОспоримая сделка может быть признана недействительной, если она нарушает права или охраняемые законом интересы лица, оспаривающего сделку, в том числе повлекла неблагоприятные для него последствия.\n\nВ случаях, когда в соответствии с законом сделка оспаривается в интересах третьих лиц, она может быть признана недействительной, если нарушает права или охраняемые законом интересы таких третьих лиц.\n\nСторона, из поведения которой явствует ее воля сохранить силу сделки, не вправе оспаривать сделку по основанию, о котором эта сторона знала или должна была знать при проявлении ее воли.\n\n3. Требование о применении последствий недействительности ничтожной сделки вправе предъявить сторона сделки, а в предусмотренных законом случаях также иное лицо.\n\nТребование о признании недействительной ничтожной сделки независимо от применения последствий ее недействительности может быть удовлетворено, если лицо, предъявляющее такое требование, имеет охраняемый законом интерес в признании этой сделки недействительной.\n\n4. Суд вправе применить последствия недействительности ничтожной сделки по своей инициативе, если это необходимо для защиты публичных интересов, и в иных предусмотренных законом случаях.\n\n5. Заявление о недействительности сделки не имеет правового значения, если ссылающееся на недействительность сделки лицо действует недобросовестно, в частности если его поведение после заключения сделки давало основание другим лицам полагаться на действительность сделки.\n\n(Статья в редакции Федерального закона от 07.05.2013 № 100-ФЗ)","article_title":"Статья 166. Оспоримые и ничтожные сделки","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"265dad5ce31852191f9ccdf6ad9729eb69adfe5cbd3e20dcee9dba1daeaa0f98"},{"code_id":"GK_RF","article_number":"167","version_date":"1994-11-30","article_text":"1. Недействительная сделка не влечет юридических последствий, за исключением тех, которые связаны с ее недействительностью, и недействительна с момента ее совершения.\n\nЛицо, которое знало или должно было знать об основаниях недействительности оспоримой сделки, после признания этой сделки недействительной не считается действовавшим добросовестно. (Дополнение абзацем - Федеральный закон от 07.05.2013 № 100-ФЗ)","article_title":"Статья 167. Общие положения о последствиях недействительности сделки","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"ff3fbae9723b359951cc4b91968a9d08694e2112ecb04cc9c788b5526967dcc8"},{"code_id":"GK_RF","article_number":"168","version_date":"1994-11-30","article_text":"1. За исключением случаев, предусмотренных пунктом 2 настоящей статьи или иным законом, сделка, нарушающая требования закона или иного правового акта, является оспоримой, если из закона не следует, что должны применяться другие последствия нарушения, не связанные с недействительностью сделки.\n\n2. Сделка, нарушающая требования закона или иного правового акта и при этом посягающая на публичные интересы либо права и охраняемые законом интересы третьих лиц, ничтожна, если из закона не следует, что такая сделка оспорима или должны применяться другие последствия нарушения, не связанные с недействительностью сделки.\n\n(Статья в редакции Федерального закона от 07.05.2013 № 100-ФЗ)","article_title":"Статья 168. Недействительность сделки, нарушающей требования закона или иного правового акта","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"7196a0073f59de6736803c4d19254108761272ed5624f94530a547d45faec599"},{"code_id":"GK_RF","article_number":"169","version_date":"1994-11-30","article_text":"Сделка, совершенная с целью, заведомо противной основам правопорядка или нравственности, ничтожна и влечет последствия, установленные статьей 167 настоящего Кодекса. В случаях, предусмотренных законом, суд может взыскать в доход Российской Федерации все полученное по такой сделке сторонами, действовавшими умышленно, или применить иные последствия, установленные законом.\n\n(Статья в редакции Федерального закона от 07.05.2013 № 100-ФЗ)","article_title":"Статья 169. Недействительность сделки, совершенной с целью, противной основам правопорядка или нравственности","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"0b6cce5e5704f1c9fd1b4a3e6d003ba6e0da47c8b5625f73956d201ab105d7eb"},{"code_id":"GK_RF","article_number":"17","version_date":"1994-11-30","article_text":"1. Способность иметь гражданские права и нести обязанности (гражданская правоспособность) признается в равной мере за всеми гражданами.\n\n2. Правоспособность гражданина возникает в момент его рождения и прекращается смертью.","article_title":"Статья 17. Правоспособность гражданина","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"f2fcdbf996094c5f359f52f9fb77141864c7330d5c31ecf4607281368e0f4254"},{"code_id":"GK_RF","article_number":"170","version_date":"1994-11-30","article_text":"1. Мнимая сделка, то есть сделка, совершенная лишь для вида, без намерения создать соответствующие ей правовые последствия, ничтожна.","article_title":"Статья 170. Недействительность мнимой и притворной сделок","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"ebb7b84dad435b3ca18c7b85ed87ee942996bda44f32f63eb3c33f135b435c24"},{"code_id":"GK_RF","article_number":"171","version_date":"1994-11-30","article_text":"1. Ничтожна сделка, совершенная гражданином, признанным недееспособным вследствие психического расстройства.\n\nКаждая из сторон такой сделки обязана возвратить другой все полученное в натуре, а при невозможности возвратить полученное в натуре - возместить его стоимость. (В редакции Федерального закона от 07.05.2013 № 100-ФЗ)\n\nДееспособная сторона обязана, кроме того, возместить другой стороне понесенный ею реальный ущерб, если дееспособная сторона знала или должна была знать о недееспособности другой стороны.\n\n2. В интересах гражданина, признанного недееспособным вследствие психического расстройства, совершенная им сделка может быть по требованию его опекуна признана судом действительной, если она совершена к выгоде этого гражданина.","article_title":"Статья 171. Недействительность сделки, совершенной гражданином, признанным недееспособным","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"9a17ee2cf716e9abeaa9f0c3f4afe9afacc0c7c08f6043fe6e97624d60749582"},{"code_id":"GK_RF","article_number":"172","version_date":"1994-11-30","article_text":"1. Ничтожна сделка, совершенная несовершеннолетним, не достигшим четырнадцати лет (малолетним). К такой сделке применяются правила, предусмотренные абзацами вторым и третьим пункта 1 статьи 171 настоящего Кодекса.\n\n2. В интересах малолетнего совершенная им сделка может быть по требованию его родителей, усыновителей или опекуна признана судом действительной, если она совершена к выгоде малолетнего.\n\n3. Правила настоящей статьи не распространяются на мелкие бытовые и другие сделки малолетних, которые они вправе совершать самостоятельно в соответствии со статьей 28 настоящего Кодекса.","article_title":"Статья 172. Недействительность сделки, совершенной несовершеннолетним, не достигшим четырнадцати лет","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"6b5ac0df6be073968ad57ec7b8cc76c74be8f9e98df5412991c8d73b2ca20518"},{"code_id":"GK_RF","article_number":"173","version_date":"1994-11-30","article_text":"Сделка, совершенная юридическим лицом в противоречии с целями деятельности, определенно ограниченными в его учредительных документах, может быть признана судом недействительной по иску этого юридического лица, его учредителя (участника) или иного лица, в интересах которого установлено ограничение, если доказано, что другая сторона сделки знала или должна была знать о таком ограничении.\n\n(Статья в редакции Федерального закона от 07.05.2013 № 100-ФЗ)","article_title":"Статья 173. Недействительность сделки юридического лица, совершенной в противоречии с целями его деятельности","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"caefb4fdacb8f144ce5419fd62da5454cc2eb02b324673a54d53db06f9ba9b7f"},{"code_id":"GK_RF","article_number":"173.1","version_date":"1994-11-30","article_text":"1. Сделка, совершенная без согласия третьего лица, органа юридического лица или государственного органа либо органа местного самоуправления, необходимость получения которого предусмотрена законом, является оспоримой, если из закона не следует, что она ничтожна или не влечет правовых последствий для лица, управомоченного давать согласие, при отсутствии такого согласия. Она может быть признана недействительной по иску такого лица или иных лиц, указанных в законе.\n\nЗаконом или в предусмотренных им случаях соглашением с лицом, согласие которого необходимо на совершение сделки, могут быть установлены иные последствия отсутствия необходимого согласия на совершение сделки, чем ее недействительность.\n\n2. Поскольку законом не установлено иное, оспоримая сделка, совершенная без необходимого в силу закона согласия третьего лица, органа юридического лица или государственного органа либо органа местного самоуправления, может быть признана недействительной, если доказано, что другая сторона сделки знала или должна была знать об отсутствии на момент совершения сделки необходимого согласия такого лица или такого органа.\n\n3. Лицо, давшее необходимое в силу закона согласие на совершение оспоримой сделки, не вправе оспаривать ее по основанию, о котором это лицо знало или должно было знать в момент выражения согласия.\n\n(Дополнение статьей - Федеральный закон от 07.05.2013 № 100-ФЗ)","article_title":"Статья 173.1. Недействительность сделки, совершенной без необходимого в силу закона согласия третьего лица, органа юридического лица или государственного органа либо органа местного самоуправления","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"f55588549e571ba205449fbd82f15df9ed3fbd3bc7b5e0eee96432e7e56bad78"},{"code_id":"GK_RF","article_number":"174","version_date":"1994-11-30","article_text":"1. Если полномочия лица на совершение сделки ограничены договором или положением о филиале или представительстве юридического лица либо полномочия действующего от имени юридического лица без доверенности органа юридического лица ограничены учредительными документами юридического лица или иными регулирующими его деятельность документами по сравнению с тем, как они определены в доверенности, в законе либо как они могут считаться очевидными из обстановки, в которой совершается сделка, и при ее совершении такое лицо или такой орган вышли за пределы этих ограничений, сделка может быть признана судом недействительной по иску лица, в интересах которого установлены ограничения, лишь в случаях, когда доказано, что другая сторона сделки знала или должна была знать об этих ограничениях.\n\n2. Сделка, совершенная представителем или действующим от имени юридического лица без доверенности органом юридического лица в ущерб интересам представляемого или интересам юридического лица, может быть признана судом недействительной по иску представляемого или по иску юридического лица, а в случаях, предусмотренных законом, по иску, предъявленному в их интересах иным лицом или иным органом, если другая сторона сделки знала или должна была знать о явном ущербе для представляемого или для юридического лица либо имели место обстоятельства, которые свидетельствовали о сговоре либо об иных совместных действиях представителя или органа юридического лица и другой стороны сделки в ущерб интересам представляемого или интересам юридического лица.\n\n(Статья в редакции Федерального закона от 07.05.2013 № 100-ФЗ)","article_title":"Статья 174. Последствия нарушения представителем или органом юридического лица условий осуществления полномочий либо интересов представляемого или интересов юридического лица","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"d40b8c4f11bf3ac0737bf455db05011e42ff2646e645874cc4040521bdc8a2da"},{"code_id":"GK_RF","article_number":"174.1","version_date":"1994-11-30","article_text":"1. Сделка, совершенная с нарушением запрета или ограничения распоряжения имуществом, вытекающих из закона, в частности из законодательства о несостоятельности (банкротстве), ничтожна в той части, в какой она предусматривает распоряжение таким имуществом (статья 180).\n\n2. Сделка, совершенная с нарушением запрета на распоряжение имуществом должника, наложенного в судебном или ином установленном законом порядке в пользу его кредитора или иного управомоченного лица, не препятствует реализации прав указанного кредитора или иного управомоченного лица, которые обеспечивались запретом, за исключением случаев, если приобретатель имущества не знал и не должен был знать о запрете.\n\n(Дополнение статьей - Федеральный закон от 07.05.2013 № 100-ФЗ)","article_title":"Статья 174.1. Последствия совершения сделки в отношении имущества, распоряжение которым запрещено или ограничено","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"eaf33dd740e59576b2879baedbf2a632c47c06d601e8e2b4a4ac522f437c4d50"},{"code_id":"GK_RF","article_number":"175","version_date":"1994-11-30","article_text":"1. Сделка, совершенная несовершеннолетним в возрасте от четырнадцати до восемнадцати лет без согласия его родителей, усыновителей или попечителя, в случаях, когда такое согласие требуется в соответствии со статьей 26 настоящего Кодекса, может быть признана судом недействительной по иску родителей, усыновителей или попечителя.\n\nЕсли такая сделка признана недействительной, соответственно применяются правила, предусмотренные абзацами вторым и третьим пункта 1 статьи 171 настоящего Кодекса.\n\n2. Правила настоящей статьи не распространяются на сделки несовершеннолетних, ставших полностью дееспособными.","article_title":"Статья 175. Недействительность сделки, совершенной несовершеннолетним в возрасте от четырнадцати до восемнадцати лет","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"536ead5f2d980a9dad0bfeaba0abaf0a81fcf3e9fff5e731466377e910f30d2e"},{"code_id":"GK_RF","article_number":"176","version_date":"1994-11-30","article_text":"Если такая сделка признана недействительной, соответственно применяются правила, предусмотренные абзацами вторым и третьим пункта 1 статьи 171 настоящего Кодекса.","article_title":"Статья 176. Недействительность сделки, совершенной гражданином, ограниченным судом в дееспособности","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"5c6dc43e48ecb711ed700e70e214952e45489340ec3a4c61205d18f40b58bed4"},{"code_id":"GK_RF","article_number":"177","version_date":"1994-11-30","article_text":"1. Сделка, совершенная гражданином, хотя и дееспособным, но находившимся в момент ее совершения в таком состоянии, когда он не был способен понимать значение своих действий или руководить ими, может быть признана судом недействительной по иску этого гражданина либо иных лиц, чьи права или охраняемые законом интересы нарушены в результате ее совершения.\n\n2. Сделка, совершенная гражданином, впоследствии признанным недееспособным, может быть признана судом недействительной по иску его опекуна, если доказано, что в момент совершения сделки гражданин не был способен понимать значение своих действий или руководить ими.\n\nСделка, совершенная гражданином, впоследствии ограниченным в дееспособности вследствие психического расстройства, может быть признана судом недействительной по иску его попечителя, если доказано, что в момент совершения сделки гражданин не был способен понимать значение своих действий или руководить ими и другая сторона сделки знала или должна была знать об этом. (Дополнение абзацем - Федеральный закон от 07.05.2013 № 100-ФЗ)\n\n3. Если сделка признана недействительной на основании настоящей статьи, соответственно применяются правила, предусмотренные абзацами вторым и третьим пункта 1 статьи 171 настоящего Кодекса.","article_title":"Статья 177. Недействительность сделки, совершенной гражданином, не способным понимать значение своих действий или руководить ими","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"97aa6fb659e51900b51890b794547a08eeb32cbdb17b846a04d2f3e719bcdbec"},{"code_id":"GK_RF","article_number":"178","version_date":"1994-11-30","article_text":"1. Сделка, совершенная под влиянием заблуждения, может быть признана судом недействительной по иску стороны, действовавшей под влиянием заблуждения, если заблуждение было настолько существенным, что эта сторона, разумно и объективно оценивая ситуацию, не совершила бы сделку, если бы знала о действительном положении дел.\n\n2. При наличии условий, предусмотренных пунктом 1 настоящей статьи, заблуждение предполагается достаточно существенным, в частности если:\n\n1) сторона допустила очевидные оговорку, описку, опечатку и т.п.;\n\n2) сторона заблуждается в отношении предмета сделки, в частности таких его качеств, которые в обороте рассматриваются как существенные;\n\n3) сторона заблуждается в отношении природы сделки;\n\n4) сторона заблуждается в отношении лица, с которым она вступает в сделку, или лица, связанного со сделкой;\n\n5) сторона заблуждается в отношении обстоятельства, которое она упоминает в своем волеизъявлении или из наличия которого она с очевидностью для другой стороны исходит, совершая сделку.\n\n3. Заблуждение относительно мотивов сделки не является достаточно существенным для признания сделки недействительной.\n\n4. Сделка не может быть признана недействительной по основаниям, предусмотренным настоящей статьей, если другая сторона выразит согласие на сохранение силы сделки на тех условиях, из представления о которых исходила сторона, действовавшая под влиянием заблуждения. В таком случае суд, отказывая в признании сделки недействительной, указывает в своем решении эти условия сделки.\n\n5. Суд может отказать в признании сделки недействительной, если заблуждение, под влиянием которого действовала сторона сделки, было таким, что его не могло бы распознать лицо, действующее с обычной осмотрительностью и с учетом содержания сделки, сопутствующих обстоятельств и особенностей сторон.\n\n6. Если сделка признана недействительной как совершенная под влиянием заблуждения, к ней применяются правила, предусмотренные статьей 167 настоящего Кодекса.\n\nСторона, по иску которой сделка признана недействительной, обязана возместить другой стороне причиненный ей вследствие этого реальный ущерб, за исключением случаев, когда другая сторона знала или должна была знать о наличии заблуждения, в том числе если заблуждение возникло вследствие зависящих от нее обстоятельств.\n\nСторона, по иску которой сделка признана недействительной, вправе требовать от другой стороны возмещения причиненных ей убытков, если докажет, что заблуждение возникло вследствие обстоятельств, за которые отвечает другая сторона.\n\n(Статья в редакции Федерального закона от 07.05.2013 № 100-ФЗ)","article_title":"Статья 178. Недействительность сделки, совершенной под влиянием существенного заблуждения","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"791a2ef0521d850dc801d5a930f64bcce3c82f57033a0c66e23f959caa9b818a"},{"code_id":"GK_RF","article_number":"179","version_date":"1994-11-30","article_text":"1. Сделка, совершенная под влиянием насилия или угрозы, может быть признана судом недействительной по иску потерпевшего.\n\n2. Сделка, совершенная под влиянием обмана, может быть признана судом недействительной по иску потерпевшего.\n\nОбманом считается также намеренное умолчание об обстоятельствах, о которых лицо должно было сообщить при той добросовестности, какая от него требовалась по условиям оборота.\n\nСделка, совершенная под влиянием обмана потерпевшего третьим лицом, может быть признана недействительной по иску потерпевшего при условии, что другая сторона либо лицо, к которому обращена односторонняя сделка, знали или должны были знать об обмане. Считается, в частности, что сторона знала об обмане, если виновное в обмане третье лицо являлось ее представителем или работником либо содействовало ей в совершении сделки.\n\nакон от 07.05.2013 № 100-ФЗ)","article_title":"Статья 179. Недействительность сделки, совершенной под влиянием обмана, насилия, угрозы или неблагоприятных обстоятельств","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"1cc7003f14ba9c7d25747f6f0bb9340f237caa22e16e5cfaca33eefb441d3536"},{"code_id":"GK_RF","article_number":"18","version_date":"1994-11-30","article_text":"Граждане могут иметь имущество на праве собственности; наследовать и завещать имущество; заниматься предпринимательской и любой иной не запрещенной законом деятельностью; создавать юридические лица самостоятельно или совместно с другими гражданами и юридическими лицами; совершать любые не противоречащие закону сделки и участвовать в обязательствах; избирать место жительства; иметь права авторов произведений науки, литературы и искусства, изобретений и иных охраняемых законом результатов интеллектуальной деятельности; иметь иные имущественные и личные неимущественные права.","article_title":"Статья 18. Содержание правоспособности граждан","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"09850dbe4326f9111ec15e5a186e476a99b1abda54c01a4250c9031eadeee7bf"},{"code_id":"GK_RF","article_number":"186","version_date":"1994-11-30","article_text":"Доверенность, в которой не указана дата ее совершения, ничтожна.","article_title":"Статья 186. Срок доверенности","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"2a74682305d497b5392c1fa76c7c991ad7a2d6f72041350d5487412e36947732"},{"code_id":"GK_RF","article_number":"187","version_date":"1994-11-30","article_text":"1. Лицо, которому выдана доверенность, должно лично совершать те действия, на которые оно уполномочено. Оно может передоверить их совершение другому лицу, если уполномочено на это доверенностью, а также если вынуждено к этому силою обстоятельств для охраны интересов выдавшего доверенность лица и доверенность не запрещает передоверие.\n\n2. Лицо, передавшее полномочия другому лицу, должно известить об этом в разумный срок выдавшее доверенность лицо и сообщить ему необходимые сведения о лице, которому переданы полномочия. Неисполнение этой обязанности возлагает на передавшее полномочия лицо ответственность за действия лица, которому оно передало полномочия, как за свои собственные.\n\n3. Доверенность, выдаваемая в порядке передоверия, должна быть нотариально удостоверена.\n\nПравило о нотариальном удостоверении доверенности, выдаваемой в порядке передоверия, не применяется к доверенностям, выдаваемым в порядке передоверия юридическими лицами, руководителями филиалов и представительств юридических лиц.\n\n4. Срок действия доверенности, выданной в порядке передоверия, не может превышать срок действия доверенности, на основании которой она выдана.\n\n5. Передоверие не допускается в случаях, предусмотренных пунктом 3 статьи 1851 настоящего Кодекса.\n\n6. Если иное не указано в доверенности или не установлено законом, представитель, передавший полномочия другому лицу в порядке передоверия, не утрачивает соответствующие полномочия.\n\n7. Передача полномочий лицом, получившим эти полномочия в результате передоверия, другому лицу (последующее передоверие) не допускается, если иное не предусмотрено в первоначальной доверенности или не установлено законом.\n\n(Статья в редакции Федерального закона от 07.05.2013 № 100-ФЗ)","article_title":"Статья 187. Передоверие","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"d6a95cead912e3ecde69a46cda09c8502d8618e01408037a7ab19deac4d93a6a"},{"code_id":"GK_RF","article_number":"188","version_date":"1994-11-30","article_text":"1. Действие доверенности прекращается вследствие:\n\n1) истечения срока доверенности;\n\n2) отмены доверенности лицом, выдавшим ее, или одним из лиц, выдавших доверенность совместно, при этом отмена доверенности совершается в той же форме, в которой была выдана доверенность, либо в нотариальной форме; (В редакции Федерального закона от 03.07.2016 № 332-ФЗ)\n\n3) отказа лица, которому выдана доверенность, от полномочий;\n\n4) прекращения юридического лица, от имени которого или которому выдана доверенность, в том числе в результате его реорганизации в форме разделения, слияния или присоединения к другому юридическому лицу;\n\n5) смерти гражданина, выдавшего доверенность, признания его недееспособным, ограниченно дееспособным или безвестно отсутствующим;\n\n6) смерти гражданина, которому выдана доверенность, признания его недееспособным, ограниченно дееспособным или безвестно отсутствующим;\n\n7) введения в отношении представляемого или представителя такой процедуры банкротства, при которой соответствующее лицо утрачивает право самостоятельно выдавать доверенности.\n\n(Пункт в редакции Федерального закона от 07.05.2013 № 100-ФЗ)","article_title":"Статья 188. Прекращение доверенности","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"90805f3d49cb9bb1dddaa62e45c4d4693d0583fa9ee4703ce93606d4cefbdda8"},{"code_id":"GK_RF","article_number":"188.1","version_date":"1994-11-30","article_text":"1. В целях исполнения или обеспечения исполнения обязательства представляемого перед представителем или лицами, от имени или в интересах которых действует представитель, в случаях, если такое обязательство связано с осуществлением предпринимательской деятельности, представляемый может указать в доверенности, выданной представителю, на то, что эта доверенность не может быть отменена до окончания срока ее действия либо может быть отменена только в предусмотренных в доверенности случаях (безотзывная доверенность).\n\nТакая доверенность в любом случае может быть отменена после прекращения того обязательства, для исполнения или обеспечения исполнения которого она выдана, а также в любое время в случае злоупотребления представителем своими полномочиями, равно как и при возникновении обстоятельств, очевидно свидетельствующих о том, что данное злоупотребление может произойти.\n\n2. Безотзывная доверенность должна быть нотариально удостоверена и содержать прямое указание на ограничение возможности ее отмены в соответствии с пунктом 1 настоящей статьи.\n\n3. Лицо, которому выдана безотзывная доверенность, не может передоверить совершение действий, на которые оно уполномочено, другому лицу, если иное не предусмотрено в доверенности.\n\n(Дополнение статьей - Федеральный закон от 07.05.2013 № 100-ФЗ)","article_title":"Статья 188.1. Безотзывная доверенность","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"837a0a60850c22d9ccb5f739d7a2ca49f21c7d7c5eef30a97d0712bc721b552b"},{"code_id":"GK_RF","article_number":"189","version_date":"1994-11-30","article_text":"Сведения о совершенной в нотариальной форме отмене доверенности вносятся нотариусом в реестр нотариальных действий, ведение которого осуществляется в электронной форме, в порядке, установленном законодательством о нотариате. (Дополнение абзацем - Федеральный закон от 07.05.2013 № 100-ФЗ) (В редакции федеральных законов от 03.07.2016 № 332-ФЗ, от 06.12.2021 № 402-ФЗ)\n\nСведения об отмене доверенности, за исключением доверенности, указанной в абзаце втором настоящего пункта, могут быть внесены в реестр распоряжений об отмене доверенностей, ведение которого осуществляется в электронной форме в порядке, установленном законодательством о нотариате. (Дополнение абзацем - Федеральный закон от 06.12.2021 № 402-ФЗ)\n\nУказанные в абзацах втором и третьем настоящего пункта сведения предоставляются Федеральной нотариальной палатой ежедневно и круглосуточно неограниченному кругу лиц без взимания платы с использованием информационно-телекоммуникационной сети \"Интернет\" в порядке, установленном законодательством о нотариате. (Дополнение абзацем - Федеральный закон от 06.12.2021 № 402-ФЗ)\n\nСведения о совершенной в простой письменной форме отмене доверенности могут быть опубликованы в официальном издании, в котором опубликовываются сведения о банкротстве. В этом случае подпись на заявлении об отмене доверенности должна быть нотариально засвидетельствована. (Дополнение абзацем - Федеральный закон от 03.07.2016 № 332-ФЗ)\n\nЕсли третьи лица не были извещены об отмене доверенности ранее, они считаются извещенными о совершенной в нотариальной форме отмене доверенности на следующий день после внесения сведений об этом в реестр нотариальных действий, а о совершенной в простой письменной форме отмене доверенности - на следующий день после внесения этих сведений в реестр распоряжений об отмене доверенностей или по истечении одного месяца со дня опубликования таких сведений в официальном издании, в котором опубликовываются сведения о банкротстве. (Дополнение абзацем - Федеральный закон от 03.07.2016 № 332-ФЗ) (В редакции Федерального закона от 06.12.2021 № 402-ФЗ)","article_title":"Статья 189. Последствия прекращения доверенности","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"ba38bbc1e7901ddc56eb51e7d6fba72a8fcd132dc2f597c97bb3efab5dfe362f"},{"code_id":"GK_RF","article_number":"19","version_date":"1994-11-30","article_text":"1. Гражданин приобретает и осуществляет права и обязанности под своим именем, включающим фамилию и собственно имя, а также отчество, если иное не вытекает из закона или национального обычая.\n\nВ случаях и в порядке, предусмотренных законом, гражданин может использовать псевдоним (вымышленное имя).\n\n2. Гражданин вправе переменить свое имя в порядке, установленном законом. Перемена гражданином имени не является основанием для прекращения или изменения его прав и обязанностей, приобретенных под прежним именем.\n\nГражданин обязан принимать необходимые меры для уведомления своих должников и кредиторов о перемене своего имени и несет риск последствий, вызванных отсутствием у этих лиц сведений о перемене его имени.\n\nГражданин, переменивший имя, вправе требовать внесения за свой счет соответствующих изменений в документы, оформленные на его прежнее имя.\n\n3. Имя, полученное гражданином при рождении, а также перемена имени подлежат регистрации в порядке, установленном для регистрации актов гражданского состояния.\n\n4. Приобретение прав и обязанностей под именем другого лица не допускается.\n\nИмя физического лица или его псевдоним могут быть использованы с согласия этого лица другими лицами в их творческой деятельности, предпринимательской или иной экономической деятельности способами, исключающими введение в заблуждение третьих лиц относительно тождества граждан, а также исключающими злоупотребление правом в других формах. (Дополнение абзацем - Федеральный закон от 30.12.2012 № 302-ФЗ)\n\n5. Вред, причиненный гражданину в результате нарушения его права на имя или псевдоним, подлежит возмещению в соответствии с настоящим Кодексом.\n\nПри искажении имени гражданина либо при использовании имени способами или в форме, которые затрагивают его честь, умаляют достоинство или деловую репутацию, гражданин вправе требовать опровержения, возмещения причиненного ему вреда, а также компенсации морального вреда.\n\n(Пункт в редакции Федерального закона от 30.12.2012 № 302-ФЗ)","article_title":"Статья 19. Имя гражданина","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"a8f666a6e53365a63a46d847a7a1266f80d7e775ea0f96e50b6f453b192d7386"},{"code_id":"GK_RF","article_number":"190","version_date":"1994-11-30","article_text":"Установленный законом, иными правовыми актами, сделкой или назначаемый судом срок определяется календарной датой или истечением периода времени, который исчисляется годами, месяцами, неделями, днями или часами.\n\nСрок может определяться также указанием на событие, которое должно неизбежно наступить.","article_title":"Статья 190. Определение срока","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"3489c007d0d800859de4549606fc5f3177d15eb4c0acfd0fe253be1eca6726c5"},{"code_id":"GK_RF","article_number":"191","version_date":"1994-11-30","article_text":"Течение срока, определенного периодом времени, начинается на следующий день после календарной даты или наступления события, которыми определено его начало.","article_title":"Статья 191. Начало срока, определенного периодом времени","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"fd5043ff5d9172d2abde774a77b822ffa422e02694f52776d7a07066941dfe7a"},{"code_id":"GK_RF","article_number":"192","version_date":"1994-11-30","article_text":"1. Срок, исчисляемый годами, истекает в соответствующие месяц и число последнего года срока.\n\nК сроку, определенному в полгода, применяются правила для сроков, исчисляемых месяцами.\n\n2. К сроку, исчисляемому кварталами года, применяются правила для сроков, исчисляемых месяцами. При этом квартал считается равным трем месяцам, а отсчет кварталов ведется с начала года.\n\n3. Срок, исчисляемый месяцами, истекает в соответствующее число последнего месяца срока.\n\nСрок, определенный в полмесяца, рассматривается как срок, исчисляемый днями, и считается равным пятнадцати дням.\n\nЕсли окончание срока, исчисляемого месяцами, приходится на такой месяц, в котором нет соответствующего числа, то срок истекает в последний день этого месяца.\n\n4. Срок, исчисляемый неделями, истекает в соответствующий день последней недели срока.","article_title":"Статья 192. Окончание срока, определенного периодом времени","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"1565d700affc4e1edd6773e704dfc5aac29f884a2dcb10d336ee0b2adc0afeea"},{"code_id":"GK_RF","article_number":"193","version_date":"1994-11-30","article_text":"Если последний день срока приходится на нерабочий день, днем окончания срока считается ближайший следующий за ним рабочий день.","article_title":"Статья 193. Окончание срока в нерабочий день","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"84a1e52bb1289fa4318d3d2a3107721f3f48515f745656bf7f3b6b2749fb05d5"},{"code_id":"GK_RF","article_number":"194","version_date":"1994-11-30","article_text":"1. Если срок установлен для совершения какого-либо действия, оно может быть выполнено до двадцати четырех часов последнего дня срока.\n\nОднако если это действие должно быть совершено в организации, то срок истекает в тот час, когда в этой организации по установленным правилам прекращаются соответствующие операции.\n\n2. Письменные заявления и извещения, сданные в организацию связи до двадцати четырех часов последнего дня срока, считаются сделанными в срок.","article_title":"Статья 194. Порядок совершения действий в последний день срока","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"01d7040152cd25586fd72c7d276c574fdb3d2a0f12e34112b4f1968ba66a67d9"},{"code_id":"GK_RF","article_number":"195","version_date":"1994-11-30","article_text":"Исковой давностью признается срок для защиты права по иску лица, право которого нарушено.","article_title":"Статья 195. Понятие исковой давности","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"ea310bb778a270cb5ef5470ba5b00142e36a6fa728c2c0a79c6926ec86881ee1"},{"code_id":"GK_RF","article_number":"196","version_date":"1994-11-30","article_text":"1. Общий срок исковой давности составляет три года со дня, определяемого в соответствии со статьей 200 настоящего Кодекса.\n\n(Статья в редакции Федерального закона от 07.05.2013 № 100-ФЗ)","article_title":"Статья 196. Общий срок исковой давности","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"b0717a8d600394ed22f017586c83f9c543cfa539934cbb84b3b571e0ab15ad37"},{"code_id":"GK_RF","article_number":"197","version_date":"1994-11-30","article_text":"1. Для отдельных видов требований законом могут устанавливаться специальные сроки исковой давности, сокращенные или более длительные по сравнению с общим сроком.","article_title":"Статья 197. Специальные сроки исковой давности","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"a817ce9cc38aeb851f88c98c44e745e52244f82cfde41a5d4ded290b179dd3af"},{"code_id":"GK_RF","article_number":"198","version_date":"1994-11-30","article_text":"Сроки исковой давности и порядок их исчисления не могут быть изменены соглашением сторон.\n\nОснования приостановления и перерыва течения сроков исковой давности устанавливаются настоящим Кодексом и иными законами.","article_title":"Статья 198. Недействительность соглашения об изменении сроков исковой давности","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"5296ac863cd7d96af026a0553e4cb40e7a453f19b69c017024bfc33dce66d806"},{"code_id":"GK_RF","article_number":"199","version_date":"1994-11-30","article_text":"1. Требование о защите нарушенного права принимается к рассмотрению судом независимо от истечения срока исковой давности.\n\n2. Исковая давность применяется судом только по заявлению стороны в споре, сделанному до вынесения судом решения.\n\nИстечение срока исковой давности, о применении которой заявлено стороной в споре, является основанием к вынесению судом решения об отказе в иске.","article_title":"Статья 199. Применение исковой давности","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"9861d378b9b2cc0a2060341b1f48f68ac85fb934fa9f406f858b6d48b9ccbec0"},{"code_id":"GK_RF","article_number":"2","version_date":"1994-11-30","article_text":"Участниками регулируемых гражданским законодательством отношений являются граждане и юридические лица. В регулируемых гражданским законодательством отношениях могут участвовать также Российская Федерация, субъекты Российской Федерации и муниципальные образования (статья 124).\n\nГражданское законодательство регулирует отношения между лицами, осуществляющими предпринимательскую деятельность, или с их участием, исходя из того, что предпринимательской является самостоятельная, осуществляемая на свой риск деятельность, направленная на систематическое получение прибыли от пользования имуществом, продажи товаров, выполнения работ или оказания услуг. Лица, осуществляющие предпринимательскую деятельность, должны быть зарегистрированы в этом качестве в установленном законом порядке, если иное не предусмотрено настоящим Кодексом. (В редакции Федерального закона от 26.07.2017 № 199-ФЗ)\n\nПравила, установленные гражданским законодательством, применяются к отношениям с участием иностранных граждан, лиц без гражданства и иностранных юридических лиц, если иное не предусмотрено федеральным законом.","article_title":"Статья 2. Отношения, регулируемые гражданским законодательством","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"da0b000bccfccd28b9e711c1be58f747d3b11fd5359f8654c1b3c68b85d272d6"},{"code_id":"GK_RF","article_number":"200","version_date":"1994-11-30","article_text":"1. Если законом не установлено иное, течение срока исковой давности начинается со дня, когда лицо узнало или должно было узнать о нарушении своего права и о том, кто является надлежащим ответчиком по иску о защите этого права.\n\n2. По обязательствам с определенным сроком исполнения течение срока исковой давности начинается по окончании срока исполнения.\n\nПо обязательствам, срок исполнения которых не определен или определен моментом востребования, срок исковой давности начинает течь со дня предъявления кредитором требования об исполнении обязательства, а если должнику предоставляется срок для исполнения такого требования, исчисление срока исковой давности начинается по окончании срока, предоставляемого для исполнения такого требования. При этом срок исковой давности во всяком случае не может превышать десять лет со дня возникновения обязательства.\n\n3. По регрессным обязательствам течение срока исковой давности начинается со дня исполнения основного обязательства.\n\n(Статья в редакции Федерального закона от 07.05.2013 № 100-ФЗ)","article_title":"Статья 200. Начало течения срока исковой давности","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"2363c31106f0dc0a49c142e9eb462008f7a4c2b7ed6ba23b18bcfe4ba90ae01e"},{"code_id":"GK_RF","article_number":"201","version_date":"1994-11-30","article_text":"Перемена лиц в обязательстве не влечет изменения срока исковой давности и порядка его исчисления.","article_title":"Статья 201. Срок исковой давности при перемене лиц в обязательстве","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"64499957fea3671b6d6247dce2cf17b582a0accd10e46fb1f02cc9dab58a5625"},{"code_id":"GK_RF","article_number":"202","version_date":"1994-11-30","article_text":"1. Течение срока исковой давности приостанавливается:\n\n1) если предъявлению иска препятствовало чрезвычайное и непредотвратимое при данных условиях обстоятельство (непреодолимая сила);\n\n2) если истец или ответчик находится в составе Вооруженных Сил Российской Федерации, переведенных на военное положение;\n\n3) в силу установленной на основании закона Правительством Российской Федерации отсрочки исполнения обязательств (мораторий);\n\n4) в силу приостановления действия закона или иного правового акта, регулирующих соответствующее отношение.\n\n2. Течение срока исковой давности приостанавливается при условии, что указанные в пункте 1 настоящей статьи обстоятельства возникли или продолжали существовать в последние шесть месяцев срока исковой давности, а если этот срок равен шести месяцам или менее шести месяцев, в течение срока исковой давности.\n\n3. Если стороны прибегли к предусмотренной законом процедуре разрешения спора во внесудебном порядке (процедура медиации, посредничество, административная процедура и т.п.), течение срока исковой давности приостанавливается на срок, установленный законом для проведения такой процедуры, а при отсутствии такого срока - на шесть месяцев со дня начала соответствующей процедуры.\n\n4. Со дня прекращения обстоятельства, послужившего основанием приостановления течения срока исковой давности, течение ее срока продолжается. Остающаяся часть срока исковой давности, если она составляет менее шести месяцев, удлиняется до шести месяцев, а если срок исковой давности равен шести месяцам или менее шести месяцев, до срока исковой давности.\n\n(Статья в редакции Федерального закона от 07.05.2013 № 100-ФЗ)","article_title":"Статья 202. Приостановление течения срока исковой давности","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"869ede2a552acee597947801d830ade5c74a6e6beef9402ee8ba4a173263d20e"},{"code_id":"GK_RF","article_number":"203","version_date":"1994-11-30","article_text":"Течение срока исковой давности прерывается совершением обязанным лицом действий, свидетельствующих о признании долга. (В редакции Федерального закона от 07.05.2013 № 100-ФЗ)\n\nПосле перерыва течение срока исковой давности начинается заново; время, истекшее до перерыва, не засчитывается в новый срок.","article_title":"Статья 203. Перерыв течения срока исковой давности","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"c468ab0a7114d7077ae2439511a51b8f28bdb54f15cdea98a7521f8a6bf0aa8d"},{"code_id":"GK_RF","article_number":"204","version_date":"1994-11-30","article_text":"1. Срок исковой давности не течет со дня обращения в суд в установленном порядке за защитой нарушенного права на протяжении всего времени, пока осуществляется судебная защита нарушенного права.\n\n2. При оставлении судом иска без рассмотрения течение срока исковой давности, начавшееся до предъявления иска, продолжается в общем порядке, если иное не вытекает из оснований, по которым осуществление судебной защиты права прекращено.\n\nЕсли судом оставлен без рассмотрения иск, предъявленный в уголовном деле, начавшееся до предъявления иска течение срока исковой давности приостанавливается до вступления в законную силу приговора, которым иск оставлен без рассмотрения.\n\n3. Если после оставления иска без рассмотрения неистекшая часть срока исковой давности составляет менее шести месяцев, она удлиняется до шести месяцев, за исключением случаев, если основанием оставления иска без рассмотрения послужили действия (бездействие) истца.\n\n(Статья в редакции Федерального закона от 07.05.2013 № 100-ФЗ)","article_title":"Статья 204. Течение срока исковой давности при защите нарушенного права в судебном порядке","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"065d9cf760f5c9a2bacdd9dc0a4d9fc0010e33486769bbfb8ec7f8011c2bc25d"},{"code_id":"GK_RF","article_number":"205","version_date":"1994-11-30","article_text":"В исключительных случаях, когда суд признает уважительной причину пропуска срока исковой давности по обстоятельствам, связанным с личностью истца (тяжелая болезнь, беспомощное состояние, неграмотность и т.п.), нарушенное право гражданина подлежит защите. Причины пропуска срока исковой давности могут признаваться уважительными, если они имели место в последние шесть месяцев срока давности, а если этот срок равен шести месяцам или менее шести месяцев - в течение срока давности.","article_title":"Статья 205. Восстановление срока исковой давности","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"e5d166166a90f44078a30a1ae43fde3e8501ab898bc29b4626347d19e7d3efcb"},{"code_id":"GK_RF","article_number":"207","version_date":"1994-11-30","article_text":"1. С истечением срока исковой давности по главному требованию считается истекшим срок исковой давности и по дополнительным требованиям (проценты, неустойка, залог, поручительство и т.п.), в том числе возникшим после истечения срока исковой давности по главному требованию.\n\n2. В случае пропуска срока предъявления к исполнению исполнительного документа по главному требованию срок исковой давности по дополнительным требованиям считается истекшим.\n\n(Статья в редакции Федерального закона от 07.05.2013 № 100-ФЗ)","article_title":"Статья 207. Применение исковой давности к дополнительным требованиям","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"5c882e25a5558166d4e997c10d6c85f81f35993f8cc011aaa46b517efdee8269"},{"code_id":"GK_RF","article_number":"208","version_date":"1994-11-30","article_text":"Исковая давность не распространяется на:\n\nтребования о защите личных неимущественных прав и других нематериальных благ, кроме случаев, предусмотренных законом;\n\nтребования вкладчиков к банку о выдаче вкладов;\n\nтребования о возмещении вреда, причиненного жизни или здоровью гражданина. Однако т\n\nребования, предъявленные по истечении трех лет с момента возникновения права на возмещение такого вреда, удовлетворяются за прошлое время не более чем за три года, предшествовавшие предъявлению иска, за исключением случаев, предусмотренных Федеральным законом от 6 марта 2006 года № 35-ФЗ \"О противодействии терроризму\"; (В редакции Федерального закона от 02.11.2013 № 302-ФЗ)\n\nтребования собственника или иного владельца об устранении всяких нарушений его права, хотя бы эти нарушения не были соединены с лишением владения (статья 304);\n\nдругие требования в случаях, установленных законом.","article_title":"Статья 208. Требования, на которые исковая давность не распространяется","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"9139f70011ffa29a27178a4870c44efb2e626f26ac1709a0aefcae184f97c0ec"},{"code_id":"GK_RF","article_number":"209","version_date":"1994-11-30","article_text":"1. Собственнику принадлежат права владения, пользования и распоряжения своим имуществом.\n\n2. Собственник вправе по своему усмотрению совершать в отношении принадлежащего ему имущества любые действия, не противоречащие закону и иным правовым актам и не нарушающие права и охраняемые законом интересы других лиц, в том числе отчуждать свое имущество в собственность другим лицам, передавать им, оставаясь собственником, права владения, пользования и распоряжения имуществом, отдавать имущество в залог и обременять его другими способами, распоряжаться им иным образом.\n\n3. Владение, пользование и распоряжение землей и другими природными ресурсами в той мере, в какой их оборот допускается законом (статья 129), осуществляются их собственником свободно, если это не наносит ущерба окружающей среде и не нарушает прав и законных интересов других лиц.\n\n4. Собственник может передать свое имущество в доверительное управление другому лицу (доверительному управляющему). Передача имущества в доверительное управление не влечет перехода права собственности к доверительному управляющему, который обязан осуществлять управление имуществом в интересах собственника или указанного им третьего лица.","article_title":"Статья 209. Содержание права собственности","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"5a5c318d973a0a1bac90013495d97a7b234cce67dcad5ae9d1c55a87d6e1236d"},{"code_id":"GK_RF","article_number":"21","version_date":"1994-11-30","article_text":"1. Способность гражданина своими действиями приобретать и осуществлять гражданские права, создавать для себя гражданские обязанности и исполнять их (гражданская дееспособность) возникает в полном объеме с наступлением совершеннолетия, то есть по достижении восемнадцатилетнего возраста.\n\n2. В случае, когда законом допускается вступление в брак до достижения восемнадцати лет, гражданин, не достигший восемнадцатилетнего возраста, приобретает дееспособность в полном объеме со времени вступления в брак.\n\nПриобретенная в результате заключения брака дееспособность сохраняется в полном объеме и в случае расторжения брака до достижения восемнадцати лет.\n\nПри признании брака недействительным суд может принять решение об утрате несовершеннолетним супругом полной дееспособности с момента, определяемого судом.","article_title":"Статья 21. Дееспособность гражданина","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"aaf7d221bb1b700eca3dcacc0e09d5bdb8f0a03e447976620138645e7330aafd"},{"code_id":"GK_RF","article_number":"210","version_date":"1994-11-30","article_text":"Собственник несет бремя содержания принадлежащего ему имущества, если иное не предусмотрено законом или договором.","article_title":"Статья 210. Бремя содержания имущества","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"2754c1f803d562c72071e556f5a287055c3270f0ed309eaf97e6011bdc048455"},{"code_id":"GK_RF","article_number":"211","version_date":"1994-11-30","article_text":"Риск случайной гибели или случайного повреждения имущества несет его собственник, если иное не предусмотрено законом или договором.","article_title":"Статья 211. Риск случайной гибели имущества","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"e83c69169a3c564abe772afb3b63b131e9ae30ffada852e6db0b5992c0451bcb"},{"code_id":"GK_RF","article_number":"212","version_date":"1994-11-30","article_text":"1. В Российской Федерации признаются частная, государственная, муниципальная и иные формы собственности.\n\n2. Имущество может находиться в собственности граждан и юридических лиц, а также Российской Федерации, субъектов Российской Федерации, муниципальных образований.\n\n3. Особенности приобретения и прекращения права собственности на имущество, владения, пользования и распоряжения им в зависимости от того, находится имущество в собственности гражданина или юридического лица, в собственности Российской Федерации, субъекта Российской Федерации или муниципального образования, могут устанавливаться лишь законом.\n\nЗаконом определяются виды имущества, которые могут находиться только в государственной или муниципальной собственности.\n\n4. Права всех собственников защищаются равным образом.","article_title":"Статья 212. Субъекты права собственности","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"13bc14e2ec729c3c72929aae40bfa2cfb5aac7f2ad132e8e3299be2d74fc1dad"},{"code_id":"GK_RF","article_number":"213","version_date":"1994-11-30","article_text":"1. В собственности граждан и юридических лиц может находиться любое имущество, за исключением отдельных видов имущества, которое в соответствии с законом не может принадлежать гражданам или юридическим лицам.\n\n2. Количество и стоимость имущества, находящегося в собственности граждан и юридических лиц, не ограничиваются, за исключением случаев, когда такие ограничения установлены законом в целях, предусмотренных пунктом 2 статьи 1 настоящего Кодекса.","article_title":"Статья 213. Право собственности граждан и юридических лиц","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"ff340daa8545edd07ab733ea2d4ec3ed6b9cea1c9351f7d352e162cd5991fd9a"},{"code_id":"GK_RF","article_number":"214","version_date":"1994-11-30","article_text":"1. Государственной собственностью в Российской Федерации является имущество, принадлежащее на праве собственности Российской Федерации (федеральная собственность), и имущество, принадлежащее на праве собственности субъектам Российской Федерации - республикам, краям, областям, городам федерального значения, автономной области, автономным округам (собственность субъекта Российской Федерации).\n\n2. Земля и другие природные ресурсы, не находящиеся в собственности граждан, юридических лиц либо муниципальных образований, являются государственной собственностью.\n\n3. От имени Российской Федерации и субъектов Российской Федерации права собственника осуществляют органы и лица, указанные в статье 125 настоящего Кодекса.\n\n4. Имущество, находящееся в государственной собственности, закрепляется за государственными предприятиями и учреждениями во владение, пользование и распоряжение в соответствии с настоящим Кодексом (статьи 294, 296).\n\nСредства соответствующего бюджета и иное государственное имущество, не закрепленное за государственными предприятиями и учреждениями, составляют государственную казну Российской Федерации, казну республики в составе Российской Федерации, казну края, области, города федерального значения, автономной области, автономного округа.\n\n5. Отнесение государственного имущества к федеральной собственности и к собственности субъектов Российской Федерации осуществляется в порядке, установленном законом.","article_title":"Статья 214. Право государственной собственности","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"61513056d91e31b24b8bea2a3ce5eeea95857286a650366c950ae41a22f8af9c"},{"code_id":"GK_RF","article_number":"215","version_date":"1994-11-30","article_text":"1. Имущество, принадлежащее на праве собственности городским и сельским поселениям, а также другим муниципальным образованиям, является муниципальной собственностью.\n\n2. От имени муниципального образования права собственника осуществляют органы местного самоуправления и лица, указанные в статье 125 настоящего Кодекса.\n\n3. Имущество, находящееся в муниципальной собственности, закрепляется за муниципальными предприятиями и учреждениями во владение, пользование и распоряжение в соответствии с настоящим Кодексом (статьи 294, 296).\n\nСредства местного бюджета и иное муниципальное имущество, не закрепленное за муниципальными предприятиями и учреждениями, составляют муниципальную казну соответствующего городского, сельского поселения или другого муниципального образования.","article_title":"Статья 215. Право муниципальной собственности","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"62a4fe3d22556fcd3ec767784a5fc4e654b49cf9d222c3effddff8499adff4b7"},{"code_id":"GK_RF","article_number":"216","version_date":"1994-11-30","article_text":"1. Вещными правами наряду с правом собственности, в частности, являются:\n\nправо пожизненного наследуемого владения земельным участком (статья 265);\n\nправо постоянного (бессрочного) пользования земельным участком (статья 268);\n\nсервитуты (статьи 274, 277);\n\nправо хозяйственного ведения имуществом (статья 294) и право оперативного управления имуществом (статья 296).\n\n2. Вещные права на имущество могут принадлежать лицам, не являющимся собственниками этого имущества.\n\n3. Переход права собственности на имущество к другому лицу не является основанием для прекращения иных вещных прав на это имущество.\n\n4. Вещные права лица, не являющегося собственником, защищаются от их нарушения любым лицом в порядке, предусмотренном статьей 305 настоящего Кодекса.","article_title":"Статья 216. Вещные права лиц, не являющихся собственниками","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"484f80e4e13f3861d28dfca1e3f7946905116f36aa9ff310f35057fc7a7839f2"},{"code_id":"GK_RF","article_number":"217","version_date":"1994-11-30","article_text":"Имущество, находящееся в государственной или муниципальной собственности, может быть передано его собственником в собственность граждан и юридических лиц в порядке, предусмотренном законами о приватизации государственного и муниципального имущества.\n\nПри приватизации государственного и муниципального имущества предусмотренные настоящим Кодексом положения, регулирующие порядок приобретения и прекращения права собственности, применяются, если законами о приватизации не предусмотрено иное.","article_title":"Статья 217. Приватизация государственного и муниципального имущества","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"4c4ad84b7d8a4197714f3b400207d993b2b5c800cd72b4f66dbe5b2d670e5cce"},{"code_id":"GK_RF","article_number":"218","version_date":"1994-11-30","article_text":"1. Право собственности на новую вещь, изготовленную или созданную лицом для себя с соблюдением закона и иных правовых актов, приобретается этим лицом.\n\nПраво собственности на плоды, продукцию, доходы, полученные в результате использования имущества, приобретается по основаниям, предусмотренным статьей 136 настоящего Кодекса.\n\n2. Право собственности на имущество, которое имеет собственника, может быть приобретено другим лицом на основании договора купли-продажи, мены, дарения или иной сделки об отчуждении этого имущества.\n\nВ случае смерти гражданина право собственности на принадлежавшее ему имущество переходит по наследству к другим лицам в соответствии с завещанием или законом.\n\nВ случае реорганизации юридического лица право собственности на принадлежавшее ему имущество переходит к юридическим лицам - правопреемникам реорганизованного юридического лица.\n\n3. В случаях и в порядке, предусмотренных настоящим Кодексом, лицо может приобрести право собственности на имущество, не имеющее собственника, на имущество, собственник которого неизвестен, либо на имущество, от которого собственник отказался или на которое он утратил право собственности по иным основаниям, предусмотренным законом.\n\n4. Член жилищного, жилищно-строительного, дачного, гаражного или иного потребительского кооператива, другие лица, имеющие право на паенакопления, полностью внесшие свой паевой взнос за квартиру, дачу, гараж, иное помещение, предоставленное этим лицам кооперативом, приобретают право собственности на указанное имущество.","article_title":"Статья 218. Основания приобретения права собственности","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"f491c174ffc81db266e49e2329200a0a266b55732784c88a690f162ea441f1cb"},{"code_id":"GK_RF","article_number":"219","version_date":"1994-11-30","article_text":"Право собственности на здания, сооружения и другое вновь создаваемое недвижимое имущество, подлежащее государственной регистрации, возникает с момента такой регистрации.","article_title":"Статья 219. Возникновение права собственности на вновь создаваемое недвижимое имущество","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"20416658158856cb439dd0bbfd8fbd75373767f6f7bb65d81e6fa5d3ddb8b18e"},{"code_id":"GK_RF","article_number":"22","version_date":"1994-11-30","article_text":"1. Никто не может быть ограничен в правоспособности и дееспособности иначе, как в случаях и в порядке, установленных законом.\n\n2. Несоблюдение установленных законом условий и порядка ограничения дееспособности граждан или их права заниматься предпринимательской либо иной деятельностью влечет недействительность акта государственного или иного органа, устанавливающего соответствующее ограничение.\n\n3. Полный или частичный отказ гражданина от правоспособности или дееспособности и другие сделки, направленные на ограничение правоспособности или дееспособности, ничтожны, за исключением случаев, когда такие сделки допускаются законом.","article_title":"Статья 22. Недопустимость лишения и ограничения правоспособности и дееспособности гражданина","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"1242579557626b387d738ed1b5dfe5f83c12d11d4c020bfc8911813c5996cf7b"},{"code_id":"GK_RF","article_number":"220","version_date":"1994-11-30","article_text":"1. Если иное не предусмотрено договором, право собственности на новую движимую вещь, изготовленную лицом путем переработки не принадлежащих ему материалов, приобретается собственником материалов.\n\nОднако если стоимость переработки существенно превышает стоимость материалов, право собственности на новую вещь приобретает лицо, которое, действуя добросовестно, осуществило переработку для себя.\n\n2. Если иное не предусмотрено договором, собственник материалов, приобретший право собственности на изготовленную из них вещь, обязан возместить стоимость переработки осуществившему ее лицу, а в случае приобретения права собственности на новую вещь этим лицом последнее обязано возместить собственнику материалов их стоимость.\n\n3. Собственник материалов, утративший их в результате недобросовестных действий лица, осуществившего переработку, вправе требовать передачи новой вещи в его собственность и возмещения причиненных ему убытков.","article_title":"Статья 220. Переработка","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"da98c1c1919f47a7e7b6569ba372f6a1700cca77135d19b4bbaa4fe60fd9b6a9"},{"code_id":"GK_RF","article_number":"221","version_date":"1994-11-30","article_text":"В случаях, когда в соответствии с законом, общим разрешением, данным собственником, или в соответствии с местным обычаем на определенной территории допускается сбор ягод, добыча (вылов) рыбы и других водных биологических ресурсов, сбор или добыча других общедоступных вещей и животных, право собственности на соответствующие вещи приобретает лицо, осуществившее их сбор или добычу. (В редакции федеральных законов от 03.06.2006 № 73-ФЗ; от 04.12.2006 № 201-ФЗ; от 06.12.2007 № 333-ФЗ)","article_title":"Статья 221. Обращение в собственность общедоступных для сбора вещей","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"8d56e105976c27a63d6ffbb76135b14b8a66c69ec4bcf86ed317eea8b68f1777"},{"code_id":"GK_RF","article_number":"222","version_date":"1994-11-30","article_text":"1. Самовольной постройкой является здание, сооружение или другое строение, возведенные или созданные на земельном участке, не предоставленном в установленном порядке, или на земельном участке, разрешенное использование которого не допускает строительства на нем данного объекта, либо возведенные или созданные без получения на это необходимых в силу закона согласований, разрешений или с нарушением градостроительных и строительных норм и правил, если разрешенное использование земельного участка, требование о получении соответствующих согласований, разрешений и (или) указанные градостроительные и строительные нормы и правила установлены на дату начала возведения или создания самовольной постройки и являются действующими на дату выявления самовольной постройки.\n\nНе является самовольной постройкой здание, сооружение или другое строение, возведенные или созданные с нарушением установленных в соответствии с законом ограничений использования земельного участка, если собственник данного объекта не знал и не мог знать о действии указанных ограничений в отношении принадлежащего ему земельного участка.\n\n(Пункт в редакции Федерального закона от 03.08.2018 № 339-ФЗ)\n\n2. Лицо, осуществившее самовольную постройку, не приобретает на нее право собственности. Оно не вправе распоряжаться постройкой - продавать, дарить, сдавать в аренду, совершать другие сделки.\n\nАбзац. (Утратил силу - Федеральный закон от 03.08.2018 № 339-ФЗ)\n\nИспользование самовольной постройки не допускается. (Дополнение абзацем - Федеральный закон от 03.08.2018 № 339-ФЗ)\n\nСамовольная постройка подлежит сносу или приведению в соответствие с параметрами, установленными правилами землепользования и застройки, документацией по планировке территории, или обязательными требованиями к параметрам постройки, предусмотренными законом (далее - установленные требования), осуществившим ее лицом либо за его счет, а при отсутствии сведений о нем лицом, в собственности, пожизненном наследуемом владении, постоянном (бессрочном) пользовании которого находится земельный участок, на котором возведена или создана самовольная постройка, или лицом, которому такой земельный участок, находящийся в государственной или муниципальной собственности, предоставлен во временное владение и пользование, либо за счет соответствующего лица, за исключением случаев, предусмотренных пунктом 3 настоящей статьи, и случаев, если снос самовольной постройки или ее приведение в соответствие с установленными требованиями осуществляется в соответствии с законом органом местного самоуправления. (Дополнение абзацем - Федеральный закон от 03.08.2018 № 339-ФЗ)\n\n3. Право собственности на самовольную постройку может быть признано судом, а в предусмотренных законом случаях в ином установленном законом порядке за лицом, в собственности, пожизненном наследуемом владении, постоянном (бессрочном) пользовании которого находится земельный участок, на котором создана постройка, при одновременном соблюдении следующих условий:\n\nесли в отношении земельного участка лицо, осуществившее постройку, имеет права, допускающие строительство на нем данного объекта;\n\nесли на день обращения в суд постройка соответствует установленным требованиям; (В редакции Федерального закона от 03.08.2018 № 339-ФЗ)\n\nесли сохранение постройки не нарушает права и охраняемые законом интересы других лиц и не создает угрозу жизни и здоровью граждан.\n\nВ этом случае лицо, за которым признано право собственности на постройку, возмещает осуществившему ее лицу расходы на постройку в размере, определенном судом.\n\n(Пункт в редакции Федерального закона от 13.07.2015 № 258-ФЗ)\n\n32. Лицо, в собственности, пожизненном наследуемом владении, постоянном (бессрочном) пользовании которого находится земельный участок, на котором возведена или создана самовольная постройка, и которое выполнило требование о приведении самовольной постройки в соответствие с установленными требованиями, приобретает право собственности на такие здание, сооружение или другое строение в соответствии с настоящим Кодексом.\n\nЛицо, во временное владение и пользование которому в целях строительства предоставлен земельный участок, который находится в государственной или муниципальной собственности и на котором возведена или создана самовольная постройка, приобретает право собственности на такие здание, сооружение или другое строение в случае выполнения им требования о приведении самовольной постройки в соответствие с установленными требованиями, если это не противоречит закону или договору.\n\nЛицо, которое приобрело право собственности на здание, сооружение или другое строение, возмещает лицу, осуществившему их строительство, расходы на постройку за вычетом расходов на приведение самовольной постройки в соответствие с установленными требованиями.\n\n(Дополнение пунктом - Федеральный закон от 03.08.2018 № 339-ФЗ)\n\n4. Органы местного самоуправления принимают в порядке, установленном законом:\n\n1) решение о сносе самовольной постройки в случае, если самовольная постройка возведена или создана на земельном участке, в отношении которого отсутствуют правоустанавливающие документы и необходимость их наличия установлена в соответствии с законодательством на дату начала строительства такого объекта, либо самовольная постройка возведена или создана на земельном участке, вид разрешенного использования которого не допускает строительства на нем такого объекта и который расположен в границах территории общего пользования;\n\n2) решение о сносе самовольной постройки или ее приведении в соответствие с установленными требованиями в случае, если самовольная постройка возведена или создана на земельном участке, вид разрешенного использования которого не допускает строительства на нем такого объекта, и данная постройка расположена в границах зоны с особыми условиями использования территории при условии, что режим указанной зоны не допускает строительства такого объекта, либо в случае, если в отношении самовольной постройки отсутствует разрешение на строительство, при условии, что границы указанной зоны, необходимость наличия этого разрешения установлены в соответствии с законодательством на дату начала строительства такого объекта.\n\nСрок для сноса самовольной постройки устанавливается с учетом характера самовольной постройки, но не может составлять менее чем три месяца и более чем двенадцать месяцев, срок для приведения самовольной постройки в соответствие с установленными требованиями устанавливается с учетом характера самовольной постройки, но не может составлять менее чем шесть месяцев и более чем три года.\n\nПредусмотренные настоящим пунктом решения не могут быть приняты органами местного самоуправления в отношении самовольных построек, возведенных или созданных на земельных участках, не находящихся в государственной или муниципальной собственности, кроме случаев, если сохранение таких построек создает угрозу жизни и здоровью граждан.\n\nОрганы местного самоуправления в любом случае не вправе принимать решение о сносе самовольной постройки либо решение о сносе самовольной постройки или ее приведении в соответствие с установленными требованиями в отношении объекта недвижимого имущества, право собственности на который зарегистрировано в Едином государствен\n\nном реестре недвижимости или признано судом в соответствии с пунктом 3 настоящей статьи либо в отношении которого ранее судом принято решение об отказе в удовлетворении исковых требований о сносе самовольной постройки, или в отношении многоквартирного дома, жилого дома или садового дома.\n\n(Дополнение пунктом - Федеральный закон от 13.07.2015 № 258-ФЗ) (В редакции Федерального закона от 03.08.2018 № 339-ФЗ)","article_title":"Статья 222. Самовольная постройка","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"c0626ea68e86b6ce518f1d1864aa1172b6dfac60b37e23bea81e71d400c825f2"},{"code_id":"GK_RF","article_number":"223","version_date":"1994-11-30","article_text":"1. Право собственности у приобретателя вещи по договору возникает с момента ее передачи, если иное не предусмотрено законом или договором.\n\n2. В случаях, когда отчуждение имущества подлежит государственной регистрации, право собственности у приобретателя возникает с момента такой регистрации, если иное не установлено законом.\n\nНедвижимое имущество признается принадлежащим добросовестному приобретателю (пункт 1 статьи 302) на праве собственности с момента такой регистрации, за исключением предусмотренных статьей 302 настоящего Кодекса случаев, когда собственник вправе истребовать такое имущество от добросовестного приобретателя. (Дополнение абзацем - Федеральный закон от 30.12.2004 № 217-ФЗ)","article_title":"Статья 223. Момент возникновения права собственности у приобретателя по договору","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"52c9f0eed45d62107018c30e84e8031de0af83d472b2735f75be2717e5105269"},{"code_id":"GK_RF","article_number":"224","version_date":"1994-11-30","article_text":"1. Передачей признается вручение вещи приобретателю, а равно сдача перевозчику для отправки приобретателю или сдача в организацию связи для пересылки приобретателю вещей, отчужденных без обязательства доставки.\n\nВещь считается врученной приобретателю с момента ее фактического поступления во владение приобретателя или указанного им лица.\n\n2. Если к моменту заключения договора об отчуждении вещи она уже находится во владении приобретателя, вещь признается переданной ему с этого момента.\n\n3. К передаче вещи приравнивается передача коносамента или иного товарораспорядительного документа на нее.","article_title":"Статья 224. Передача вещи","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"704fb0e779a29fe4f67f0ed955bd4940caaaf359500cb625fb18355b97b81f7b"},{"code_id":"GK_RF","article_number":"225","version_date":"1994-11-30","article_text":"Если иной срок не предусмотрен настоящей статьей, по истечении года со дня постановки бесхозяйной недвижимой вещи на учет орган, уполномоченный управлять муниципальным имуществом, может обратиться в суд с требованием о признании права муниципальной собственности на эту вещь. (В редакции  Федерального закона от 31.07.2025 № 315-ФЗ)\n\nБесхозяйная недвижимая вещь, не признанная по решению суда поступившей в муниципальную собственность, может быть вновь принята во владение, пользование и распоряжение оставившим ее собственником либо приобретена в собственность в силу приобретательной давности.\n\nЕсли иной срок не предусмотрен настоящей статьей, по истечении года со дня постановки бесхозяйной недвижимой вещи на учет уполномоченный государственный орган города федерального значения Москвы, Санкт-Петербурга или Севастополя может обратиться в суд с требованием о признании права собственности города федерального значения Москвы, Санкт-Петербурга или Севастополя на данную вещь. (В редакции  Федерального закона от 31.07.2025 № 315-ФЗ)\n\nБесхозяйная недвижимая вещь, не признанная по решению суда поступившей в собственность города федерального значения Москвы, Санкт-Петербурга или Севастополя, может быть вновь принята во владение, в пользование и в распоряжение оставившим ее собственником либо приобретена в собственность в силу приобретательной давности. (В редакции Федерального закона от 03.07.2016 № 333-ФЗ)\n\n(Дополнение пунктом - Федеральный закон от 09.02.2009 № 7-ФЗ)\n\nПо истечении трех месяцев со дня постановки указанных в пунктах 5 и 6 настоящей статьи бесхозяйных объектов на учет лица, обязанные в соответствии с законом осуществлять эксплуатацию таких объектов, также могут обратиться в суд с требованием о признании права собственности на такие объекты.\n\n(Дополнение пунктом - Федеральный закон от 31.07.2025 № 315-ФЗ)","article_title":"Статья 225. Бесхозяйные вещи","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"da7308a4a711fd45cbf471865c5f3319f077e75355e3b6f1516287f338f9fd0c"},{"code_id":"GK_RF","article_number":"226","version_date":"1994-11-30","article_text":"1. Движимые вещи, брошенные собственником или иным образом оставленные им с целью отказа от права собственности на них (брошенные вещи), могут быть обращены другими лицами в свою собственность в порядке, предусмотренном пунктом 2 настоящей статьи.\n\nДругие брошенные вещи поступают в собственность лица, вступившего во владение ими, если по заявлению этого лица они признаны судом бесхозяйными.","article_title":"Статья 226. Движимые вещи, от которых собственник отказался","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"ef1657d7f2e53dbae844310530cb2323bdfb67005a6f474311e7d5c2481d44d9"},{"code_id":"GK_RF","article_number":"227","version_date":"1994-11-30","article_text":"1. Нашедший потерянную вещь обязан немедленно уведомить об этом лицо, потерявшее ее, или собственника вещи или кого-либо другого из известных ему лиц, имеющих право получить ее, и возвратить найденную вещь этому лицу.\n\nЕсли вещь найдена в помещении или на транспорте, она подлежит сдаче лицу, представляющему владельца этого помещения или средства транспорта. В этом случае лицо, которому сдана находка, приобретает права и несет обязанности лица, нашедшего вещь.\n\nСкоропортящаяся вещь или вещь, издержки по хранению которой несоизмеримо велики по сравнению с ее стоимостью, может быть реализована нашедшим вещь с получением письменных доказательств, удостоверяющих сумму выручки. Деньги, вырученные от продажи найденной вещи, подлежат возврату лицу, управомоченному на ее получение.","article_title":"Статья 227. Находка","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"9e2fb2d9bbd8ab65239dca750b44ab2fe9ab09b81bed1eefe0c1057130cc4cca"},{"code_id":"GK_RF","article_number":"229","version_date":"1994-11-30","article_text":"1. Нашедший и возвративший вещь лицу, управомоченному на ее получение, вправе получить от этого лица, а в случаях перехода вещи в муниципальную собственность - от соответствующего органа местного самоуправления возмещение необходимых расходов, связанных с хранением, сдачей или реализацией вещи, а также затрат на обнаружение лица, управомоченного получить вещь.\n\n2. Нашедший вещь вправе потребовать от лица, управомоченного на получение вещи, вознаграждение за находку в размере до двадцати процентов стоимости вещи. Если найденная вещь представляет ценность только для лица, управомоченного на ее получение, размер вознаграждения определяется по соглашению с этим лицом.\n\nПраво на вознаграждение не возникает, если нашедший вещь не заявил о находке или пытался ее утаить.","article_title":"Статья 229. Возмещение расходов, связанных с находкой, и вознаграждение нашедшему вещь","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"9c1d15aa51fce49cc88dd208976489792e1dd8ba2ce22dcefe9557d9d3b94eda"},{"code_id":"GK_RF","article_number":"23","version_date":"1994-11-30","article_text":"1. Гражданин вправе заниматься предпринимательской деятельностью без образования юридического лица с момента государственной регистрации в качестве индивидуального предпринимателя, за исключением случаев, предусмотренных абзацем вторым настоящего пункта.\n\nВ отношении отдельных видов предпринимательской деятельности законом могут быть предусмотрены условия осуществления гражданами такой деятельности без государственной регистрации в качестве индивидуального предпринимателя.\n\n(Пункт в редакции Федерального закона от 26.07.2017 № 199-ФЗ)\n\nГлавой крестьянского (фермерского) хозяйства может быть гражданин, зарегистрированный в качестве индивидуального предпринимателя.\n\n(Дополнение пунктом - Федеральный закон от 30.12.2012 № 302-ФЗ)","article_title":"Статья 23. Предпринимательская деятельность гражданина","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"3e3ce314b2d00b042f38d1d91f60f34c06289397ebefe09907862355142f694f"},{"code_id":"GK_RF","article_number":"231","version_date":"1994-11-30","article_text":"1. Если в течение шести месяцев с момента заявления о задержании безнадзорных домашних животных их собственник не будет обнаружен или сам не заявит о своем праве на них, лицо, у которого животные находились на содержании и в пользовании, приобретает право собственности на них.\n\nПри отказе этого лица от приобретения в собственность содержавшихся у него животных они поступают в муниципальную собственность и используются в порядке, определяемом органом местного самоуправления.\n\n2. В случае явки прежнего собственника животных после перехода их в собственность другого лица прежний собственник вправе при наличии обстоятельств, свидетельствующих о сохранении к нему привязанности со стороны этих животных или о жестоком либо ином ненадлежащем обращении с ними нового собственника, потребовать их возврата на условиях, определяемых по соглашению с новым собственником, а при недостижении соглашения - судом.","article_title":"Статья 231. Приобретение права собственности на безнадзорных животных","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"8ea1e904069eeb1240a4b953f7efc894462976875cf07c29525137642df80a8e"},{"code_id":"GK_RF","article_number":"232","version_date":"1994-11-30","article_text":"В случае возврата безнадзорных домашних животных собственнику лицо, задержавшее животных, и лицо, у которого они находились на содержании и в пользовании, имеют право на возмещение их собственником необходимых расходов, связанных с содержанием животных, с зачетом выгод, извлеченных от пользования ими.\n\nЛицо, задержавшее безнадзорных домашних животных, имеет право на вознаграждение в соответствии с пунктом 2 статьи 229 настоящего Кодекса.","article_title":"Статья 232. Возмещение расходов на содержание безнадзорных животных и вознаграждение за них","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"671275c17e8f2ff68b0d2a74e6ded70e4f6d5e4d6ab3d3d96c7e60ba4b2eeebc"},{"code_id":"GK_RF","article_number":"233","version_date":"1994-11-30","article_text":"1. Клад, то есть зарытые в земле или сокрытые иным способом деньги или ценные предметы, собственник которых не может быть установлен либо в силу закона утратил на них право, поступает в собственность лица, которому принадлежит имущество (земельный участок, строение и т.п.), где клад был сокрыт, и лица, обнаружившего клад, в равных долях, если соглашением между ними не установлено иное.\n\nПри обнаружении клада лицом, производившим раскопки или поиск ценностей без согласия на это собственника земельного участка или иного имущества, где клад был сокрыт, клад подлежит передаче собственнику земельного участка или иного имущества, где был обнаружен клад.\n\nПри обнаружении такого клада лицом, производившим раскопки или поиски ценностей без согласия собственника имущества, где клад был сокрыт, вознаграждение этому лицу не выплачиваются и полностью поступает собственнику.","article_title":"Статья 233. Клад","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"9b90528e28a7813d86e5ccbb6b2ce78fe5cd96e4aed644b9dfb1bb6dca3dcaf5"}]$law7v007$::jsonb) as x(code_id text,article_number text,version_date date,article_text text,article_title text,amendment_eo_number text,amendment_date date,is_current boolean,is_repealed boolean,repealed_date date,text_hash text)) insert into law7_mirror.article_versions(code_id,article_number,version_date,article_text,article_title,amendment_eo_number,amendment_date,is_current,is_repealed,repealed_date,text_hash,source_commit,imported_at) select code_id,article_number,version_date,article_text,article_title,amendment_eo_number,amendment_date,is_current,is_repealed,repealed_date,text_hash,'70a1d8fc6b27b67ad7f12f03f017d02b5f68a0c895447159039800965895f8b2',now() from j on conflict (code_id,article_number,version_date) do update set article_text=excluded.article_text,article_title=excluded.article_title,amendment_eo_number=excluded.amendment_eo_number,amendment_date=excluded.amendment_date,is_current=excluded.is_current,is_repealed=excluded.is_repealed,repealed_date=excluded.repealed_date,text_hash=excluded.text_hash,source_commit=excluded.source_commit,imported_at=now();
    commit;
